"""Stateless MCP server, registry metadata, policy, and audit simulation.

This stdlib-only model keeps two discovery layers separate:

* ``server.json`` describes installation and remote transport metadata to a
  registry.
* ``server/discover`` reports live protocol versions and capabilities.

It does not open a network listener, validate a real OAuth token, call OPA, or
publish to a registry. Run with ``python3 code/main.py`` from the lesson root.
"""

from __future__ import annotations

import hashlib
import json
import re
import time
from copy import deepcopy
from dataclasses import asdict, dataclass, field
from typing import Callable


PROTOCOL_VERSION = "2026-07-28"
REGISTRY_SCHEMA = "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json"
PUBLISHER_DOMAIN = "example.com"
SERVER_NAME_RE = re.compile(r"^[a-zA-Z0-9.-]+/[a-zA-Z0-9._-]+$")
DOMAIN_LABEL_RE = re.compile(r"^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$")
REMOTE_URL_RE = re.compile(r"^https?://\S+$")
VERSION_RANGE_RE = re.compile(r"(?:^[~^<>=]|[*]|(?:^|\.)x(?:$|\.))", re.IGNORECASE)


def request_meta() -> dict:
    return {
        "io.modelcontextprotocol/protocolVersion": PROTOCOL_VERSION,
        "io.modelcontextprotocol/clientCapabilities": {},
        "io.modelcontextprotocol/clientInfo": {
            "name": "registry-capstone-client",
            "version": "1.0.0",
        },
    }


def error(code: int, message: str, data: dict | None = None) -> dict:
    detail = {"code": code, "message": message}
    if data is not None:
        detail["data"] = data
    return {"error": detail}


def validate_meta(meta: object) -> dict | None:
    if not isinstance(meta, dict):
        return error(-32602, "params._meta must be an object")
    requested = meta.get("io.modelcontextprotocol/protocolVersion")
    if not isinstance(requested, str):
        return error(-32602, "protocolVersion must be a string")
    if requested != PROTOCOL_VERSION:
        return error(
            -32022,
            "Unsupported protocol version",
            {"supported": [PROTOCOL_VERSION], "requested": requested},
        )
    if not isinstance(meta.get("io.modelcontextprotocol/clientCapabilities"), dict):
        return error(-32602, "clientCapabilities must be an object")
    return None


@dataclass(frozen=True)
class ToolSchema:
    name: str
    required_scope: str
    destructive: bool
    description: str
    input_schema: dict


Handler = Callable[[dict], dict]


@dataclass
class MCPServer:
    name: str
    title: str
    description: str
    version: str
    url: str
    trusted_issuer: str
    tools: dict[str, ToolSchema] = field(default_factory=dict)
    handlers: dict[str, Handler] = field(default_factory=dict)

    @property
    def server_info(self) -> dict:
        return {"name": self.name, "version": self.version}

    def register(self, schema: ToolSchema, handler: Handler) -> None:
        if schema.name in self.tools:
            raise ValueError(f"duplicate tool: {schema.name}")
        self.tools[schema.name] = schema
        self.handlers[schema.name] = handler

    def result(self, **fields: object) -> dict:
        return {
            "resultType": "complete",
            **fields,
            "_meta": {"io.modelcontextprotocol/serverInfo": self.server_info},
        }

    def discover(self, meta: dict) -> dict:
        invalid = validate_meta(meta)
        if invalid:
            return invalid
        return self.result(
            supportedVersions=[PROTOCOL_VERSION],
            capabilities={"tools": {"listChanged": False}},
            ttlMs=3_600_000,
            cacheScope="public",
        )

    def tools_list(self, meta: dict) -> dict:
        invalid = validate_meta(meta)
        if invalid:
            return invalid
        tools = [
            {
                "name": tool.name,
                "description": tool.description,
                "inputSchema": tool.input_schema,
                "annotations": {
                    "readOnlyHint": not tool.destructive,
                    "destructiveHint": tool.destructive,
                },
            }
            for tool in sorted(self.tools.values(), key=lambda item: item.name)
        ]
        return self.result(tools=tools, ttlMs=60_000, cacheScope="private")

    def registry_document(self) -> dict:
        return {
            "$schema": REGISTRY_SCHEMA,
            "name": self.name,
            "title": self.title,
            "description": self.description,
            "version": self.version,
            "remotes": [{"type": "streamable-http", "url": self.url}],
        }


@dataclass(frozen=True)
class Token:
    user: str
    issuer: str
    audience: str
    scopes: frozenset[str]
    expires_at: float

    def has_scope(self, scope: str) -> bool:
        return scope in self.scopes

    def is_expired(self, now: float) -> bool:
        return now >= self.expires_at


def arguments_digest(args: dict) -> str:
    normalized = json.dumps(
        args,
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    )
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()


@dataclass(frozen=True)
class ApprovalRecord:
    actor: str
    tool: str
    arguments_digest: str
    target: str
    expires_at: float

    @classmethod
    def for_action(
        cls,
        actor: str,
        tool: str,
        args: dict,
        target: str,
        expires_at: float,
    ) -> ApprovalRecord:
        return cls(actor, tool, arguments_digest(args), target, expires_at)

    def authorize(
        self,
        actor: str,
        tool: str,
        args: dict,
        target: str,
        now: float,
    ) -> tuple[bool, str]:
        if self.actor != actor:
            return False, "approval actor does not match token subject"
        if self.tool != tool:
            return False, "approval tool does not match requested tool"
        if self.target != target:
            return False, "approval target does not match this server"
        if self.arguments_digest != arguments_digest(args):
            return False, "approval arguments do not match requested action"
        if now >= self.expires_at:
            return False, "approval has expired"
        return True, "ok"


def policy_decide(
    server: MCPServer,
    tool: str,
    token: Token,
    args: dict,
    now: float,
    approval: ApprovalRecord | None = None,
) -> tuple[bool, str]:
    if token.issuer != server.trusted_issuer:
        return False, "token issuer is not trusted by this server"
    if token.audience != server.url:
        return False, "token audience does not match this server"
    if token.is_expired(now):
        return False, "token has expired"
    schema = server.tools.get(tool)
    if schema is None:
        return False, f"no such tool: {tool}"
    if not token.has_scope(schema.required_scope):
        return False, f"missing scope: {schema.required_scope}"
    if len(json.dumps(args)) > 8192:
        return False, "payload too large"
    if schema.destructive:
        if approval is None:
            return False, "destructive tool requires an action-bound approval"
        approved, reason = approval.authorize(
            token.user,
            tool,
            args,
            server.url,
            now,
        )
        if not approved:
            return False, reason
    return True, "ok"


def redact(payload: dict) -> dict:
    text = json.dumps(payload)
    text = re.sub(r"[\w.+-]+@[\w-]+\.[\w.-]+", "[email]", text)
    text = re.sub(r"\b\d{3}-\d{2}-\d{4}\b", "[ssn]", text)
    return json.loads(text)


@dataclass(frozen=True)
class AuditEntry:
    ts: float
    user: str
    issuer: str
    tool: str
    outcome: str
    args_redacted: dict
    response_redacted: dict


def dispatch(
    server: MCPServer,
    token: Token,
    tool: str,
    args: dict,
    meta: dict,
    audit: list[AuditEntry],
    approval: ApprovalRecord | None = None,
) -> dict:
    invalid = validate_meta(meta)
    if invalid:
        return invalid
    now = time.time()
    allowed, reason = policy_decide(server, tool, token, args, now, approval)
    if not allowed:
        audit.append(
            AuditEntry(now, token.user, token.issuer, tool, f"denied:{reason}", redact(args), {})
        )
        return error(-32000, reason)
    try:
        response = server.handlers[tool](args)
    except Exception as exc:
        audit.append(
            AuditEntry(now, token.user, token.issuer, tool, "handler_error", redact(args), {})
        )
        return server.result(
            content=[{"type": "text", "text": str(exc)}],
            isError=True,
        )
    audit.append(
        AuditEntry(
            now,
            token.user,
            token.issuer,
            tool,
            "allowed",
            redact(args),
            redact(response),
        )
    )
    return server.result(
        content=[{"type": "text", "text": json.dumps(response)}],
        structuredContent=response,
        isError=False,
    )


def validate_registry_document(document: object) -> list[str]:
    """Validate the official fields used by this lesson's remote-only profile.

    This dependency-free subset is not a replacement for validation against
    the complete pinned Registry JSON Schema before publication.
    """
    if not isinstance(document, dict):
        return ["server.json must be an object"]
    issues: list[str] = []

    for key in ("name", "description", "version"):
        if key not in document:
            issues.append(f"missing {key}")

    schema_uri = document.get("$schema")
    if "$schema" in document and schema_uri != REGISTRY_SCHEMA:
        issues.append("unsupported registry schema")

    name = document.get("name")
    if "name" in document and (
        not isinstance(name, str)
        or not 3 <= len(name) <= 200
        or SERVER_NAME_RE.fullmatch(name) is None
    ):
        issues.append("name must match namespace/server and be 3-200 characters")

    description = document.get("description")
    if "description" in document and (
        not isinstance(description, str) or not 1 <= len(description) <= 100
    ):
        issues.append("description must be a 1-100 character string")

    title = document.get("title")
    if "title" in document and (
        not isinstance(title, str) or not 1 <= len(title) <= 100
    ):
        issues.append("title must be a 1-100 character string")

    version = document.get("version")
    if "version" in document and (
        not isinstance(version, str)
        or not 1 <= len(version) <= 255
        or VERSION_RANGE_RE.search(version) is not None
        or version.casefold() == "latest"
    ):
        issues.append("version must be one concrete 1-255 character version")

    remotes = document.get("remotes")
    if not isinstance(remotes, list) or not remotes:
        issues.append("remote profile requires a non-empty remotes list")
    else:
        for index, remote in enumerate(remotes):
            if not isinstance(remote, dict):
                issues.append(f"remotes[{index}] must be an object")
                continue
            if remote.get("type") not in {"streamable-http", "sse"}:
                issues.append(f"remotes[{index}].type must be streamable-http or sse")
            remote_url = remote.get("url")
            if not isinstance(remote_url, str) or REMOTE_URL_RE.fullmatch(remote_url) is None:
                issues.append(f"remotes[{index}].url must be an http(s) URL template")
    return issues


def reverse_dns_namespace(domain: str) -> str:
    normalized = domain.casefold().rstrip(".")
    labels = normalized.split(".")
    if len(labels) < 2 or any(DOMAIN_LABEL_RE.fullmatch(label) is None for label in labels):
        raise ValueError("publisher domain must be a valid multi-label DNS name")
    return ".".join(reversed(labels))


def validate_publisher_namespace(document: object, verified_domain: str) -> list[str]:
    """Check domain ownership outside the server.json shape contract."""
    if not isinstance(document, dict) or not isinstance(document.get("name"), str):
        return []
    namespace = document["name"].partition("/")[0]
    expected = reverse_dns_namespace(verified_domain)
    if namespace != expected and not namespace.startswith(f"{expected}."):
        return [
            f"name namespace must be {expected} or its child for verified domain {verified_domain}"
        ]
    return []


def validate_runtime_alignment(document: dict, discovery: object) -> list[str]:
    """Compare publication identity with the live server/discover identity."""
    if not isinstance(discovery, dict):
        return ["server/discover result must be an object"]
    meta = discovery.get("_meta")
    server_info = (
        meta.get("io.modelcontextprotocol/serverInfo") if isinstance(meta, dict) else None
    )
    if not isinstance(server_info, dict):
        return ["server/discover must include serverInfo for registry drift checks"]

    issues: list[str] = []
    if server_info.get("name") != document.get("name"):
        issues.append("runtime serverInfo.name does not match server.json name")
    if server_info.get("version") != document.get("version"):
        issues.append("runtime serverInfo.version does not match server.json version")
    return issues


@dataclass
class Registry:
    publisher_domain: str = PUBLISHER_DOMAIN
    entries: dict[str, dict] = field(default_factory=dict)
    runtime_discovery: dict[str, dict] = field(default_factory=dict)

    def register(self, server: MCPServer) -> None:
        document = server.registry_document()
        issues = validate_registry_document(document)
        issues.extend(validate_publisher_namespace(document, self.publisher_domain))
        if issues:
            raise ValueError("; ".join(issues))
        discovery = server.discover(request_meta())
        if "error" in discovery:
            raise ValueError("runtime discovery failed")
        alignment_issues = validate_runtime_alignment(document, discovery)
        if alignment_issues:
            raise ValueError("; ".join(alignment_issues))
        self.entries[server.name] = deepcopy(document)
        self.runtime_discovery[server.name] = deepcopy(discovery)

    def search(self, query: str) -> list[str]:
        needle = query.casefold()
        return sorted(
            name
            for name, entry in self.entries.items()
            if needle in name.casefold()
            or needle in entry["title"].casefold()
            or needle in entry["description"].casefold()
        )


def build_readonly_server() -> MCPServer:
    server = MCPServer(
        name="com.example/internal-readonly",
        title="Internal Read-Only Tools",
        description="Read-only incident and data lookup tools.",
        version="1.0.0",
        url="https://mcp.internal.example.com/readonly",
        trusted_issuer="https://auth.internal.example.com",
    )
    server.register(
        ToolSchema(
            "postgres.readonly",
            "postgres:query:readonly",
            False,
            "Run an approved read-only query.",
            {
                "type": "object",
                "properties": {"sql": {"type": "string"}},
                "required": ["sql"],
                "additionalProperties": False,
            },
        ),
        lambda args: {"rows": [[1]], "sql": args["sql"]},
    )
    server.register(
        ToolSchema(
            "s3.list",
            "s3:list",
            False,
            "List objects in one approved bucket.",
            {
                "type": "object",
                "properties": {"bucket": {"type": "string"}},
                "required": ["bucket"],
                "additionalProperties": False,
            },
        ),
        lambda args: {"bucket": args["bucket"], "objects": ["a/b.txt"]},
    )
    return server


def build_destructive_server() -> MCPServer:
    server = MCPServer(
        name="com.example/internal-destructive",
        title="Internal Destructive Tools",
        description="State-changing tools behind explicit approval.",
        version="1.0.0",
        url="https://mcp.internal.example.com/destructive",
        trusted_issuer="https://auth.internal.example.com",
    )
    server.register(
        ToolSchema(
            "jira.create",
            "jira:write",
            True,
            "Create one Jira issue after explicit approval.",
            {
                "type": "object",
                "properties": {"title": {"type": "string"}},
                "required": ["title"],
                "additionalProperties": False,
            },
        ),
        lambda args: {"id": "PROJ-99", "title": args["title"], "created": True},
    )
    return server


def main() -> None:
    readonly = build_readonly_server()
    destructive = build_destructive_server()
    registry = Registry()
    registry.register(readonly)
    registry.register(destructive)
    audit: list[AuditEntry] = []

    readonly_token = Token(
        "u42",
        readonly.trusted_issuer,
        readonly.url,
        frozenset({"postgres:query:readonly", "s3:list"}),
        time.time() + 3_600,
    )
    approved_token = Token(
        "u42",
        destructive.trusted_issuer,
        destructive.url,
        frozenset({"jira:write"}),
        time.time() + 3_600,
    )
    approved_args = {"title": "new bug"}
    approval = ApprovalRecord.for_action(
        approved_token.user,
        "jira.create",
        approved_args,
        destructive.url,
        time.time() + 900,
    )

    print("=== registry metadata and runtime discovery ===")
    print(json.dumps(registry.entries[readonly.name], indent=2))
    print(json.dumps(registry.runtime_discovery[readonly.name], indent=2))
    print("tools:", json.dumps(readonly.tools_list(request_meta()), indent=2))

    print("\n=== policy-gated calls ===")
    print(
        dispatch(
            readonly,
            readonly_token,
            "postgres.readonly",
            {"sql": "SELECT 1"},
            request_meta(),
            audit,
        )
    )
    print(
        dispatch(
            destructive,
            approved_token,
            "jira.create",
            approved_args,
            request_meta(),
            audit,
            approval,
        )
    )

    print("\n=== audit log ===")
    for entry in audit:
        print(json.dumps(asdict(entry), sort_keys=True))


if __name__ == "__main__":
    main()

"""Agent harness loop contract — deterministic state machine, hooks, pull points.

Conceptual references:
- ./docs/en.md (this lesson)
- Phase 14 lesson 01 (agent loop fundamentals)
- Phase 13 lesson 02 (tool protocols overview)

Stdlib only. Run: python3 code/main.py
"""

from __future__ import annotations

import json
import time
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Callable, Iterable


class State(str, Enum):
    IDLE = "idle"
    PLANNING = "planning"
    EXECUTING = "executing"
    AWAITING_TOOL = "awaiting_tool"
    REFLECTING = "reflecting"
    DONE = "done"


HOOK_TOPICS = (
    "before_plan",
    "after_plan",
    "before_step",
    "after_step",
    "before_tool_call",
    "after_tool_call",
    "on_error",
    "on_pause",
    "on_budget_exceeded",
    "on_complete",
)

EVENT_TYPES = (
    "session.start",
    "plan.draft",
    "plan.commit",
    "step.start",
    "step.end",
    "tool.call",
    "tool.result",
    "tool.error",
    "budget.warn",
    "session.pause",
    "session.complete",
)


class HookAbort(Exception):
    """Raised by a hook to cancel the in-flight turn."""


@dataclass
class Event:
    type: str
    payload: dict
    ts: float

    def to_dict(self) -> dict:
        return {"type": self.type, "payload": self.payload, "ts": self.ts}


@dataclass
class Budget:
    max_turns: int = 8
    max_tool_calls: int = 16
    max_wall_seconds: float = 30.0
    turns: int = 0
    tool_calls: int = 0
    started_at: float = field(default_factory=time.time)

    def remaining_seconds(self) -> float:
        return max(0.0, self.max_wall_seconds - (time.time() - self.started_at))

    def exceeded(self) -> str | None:
        if self.turns >= self.max_turns:
            return "turns"
        if self.tool_calls >= self.max_tool_calls:
            return "tool_calls"
        if self.remaining_seconds() <= 0.0:
            return "wall_clock"
        return None


@dataclass
class Step:
    id: int
    description: str
    requires_tool: bool
    tool_name: str | None = None
    tool_args: dict = field(default_factory=dict)
    result: Any = None
    error: str | None = None


@dataclass
class PullRequest:
    """Returned from run()/resume() when the loop yields control."""
    reason: str
    state: State
    payload: dict


@dataclass
class SessionResult:
    state: State
    reason: str
    steps: list[Step]
    events: list[Event]


class HookRegistry:
    def __init__(self) -> None:
        self._subs: dict[str, list[Callable[[dict], Any]]] = {t: [] for t in HOOK_TOPICS}

    def on(self, topic: str, fn: Callable[[dict], Any]) -> None:
        if topic not in self._subs:
            raise ValueError(f"unknown hook topic: {topic}")
        self._subs[topic].append(fn)

    def fire(self, topic: str, payload: dict) -> list[Any]:
        results = []
        for fn in self._subs[topic]:
            results.append(fn(payload))
        return results


Planner = Callable[[str, list[Step]], list[Step]]


def _default_planner(goal: str, history: list[Step]) -> list[Step]:
    """Deterministic stand-in planner. Returns a fixed three-step plan."""
    if history:
        return []
    return [
        Step(id=1, description=f"interpret goal: {goal}", requires_tool=False),
        Step(id=2, description="fetch user record", requires_tool=True,
             tool_name="db.get_user", tool_args={"id": 42}),
        Step(id=3, description="summarize and respond", requires_tool=True,
             tool_name="format.summary", tool_args={"style": "short"}),
    ]


class HarnessLoop:
    """Six-state deterministic loop with hook topics and event stream."""

    def __init__(
        self,
        planner: Planner | None = None,
        budget: Budget | None = None,
    ) -> None:
        self.state: State = State.IDLE
        self.hooks = HookRegistry()
        self.budget = budget or Budget()
        self._planner: Planner = planner or _default_planner
        self._goal: str = ""
        self._plan: list[Step] = []
        self._cursor: int = 0
        self._events: list[Event] = []
        self._history: list[Step] = []
        self._reason: str = ""
        self._prev_state: State | None = None

    @property
    def events(self) -> list[Event]:
        return list(self._events)

    @property
    def plan(self) -> list[Step]:
        return list(self._plan)

    def _emit(self, etype: str, payload: dict) -> None:
        if etype not in EVENT_TYPES:
            raise ValueError(f"unknown event type: {etype}")
        self._events.append(Event(type=etype, payload=payload, ts=time.time()))

    def _transition(self, target: State) -> None:
        legal: dict[State, set[State]] = {
            State.IDLE: {State.PLANNING},
            State.PLANNING: {State.EXECUTING, State.IDLE, State.DONE},
            State.EXECUTING: {State.AWAITING_TOOL, State.REFLECTING, State.IDLE},
            State.AWAITING_TOOL: {State.REFLECTING, State.IDLE},
            State.REFLECTING: {State.PLANNING, State.EXECUTING, State.DONE, State.IDLE},
            State.DONE: set(),
        }
        if target not in legal[self.state]:
            raise RuntimeError(f"illegal transition {self.state.value} -> {target.value}")
        self.state = target

    def _check_budget(self) -> PullRequest | None:
        which = self.budget.exceeded()
        if which is None:
            return None
        self._emit("budget.warn", {"limit": which})
        self.hooks.fire("on_budget_exceeded", {"limit": which, "budget": self.budget})
        self._reason = f"budget_exceeded:{which}"
        self._prev_state = self.state
        return self._pause(self._reason)

    def _pause(self, reason: str) -> PullRequest:
        self._emit("session.pause", {"reason": reason})
        self.hooks.fire("on_pause", {"reason": reason})
        self._transition(State.IDLE)
        return PullRequest(reason=reason, state=self.state, payload={"reason": reason})

    def run(self, goal: str) -> PullRequest | SessionResult:
        if self.state != State.IDLE:
            raise RuntimeError(f"run() requires IDLE, got {self.state.value}")
        self._goal = goal
        self.budget.started_at = time.time()
        self._emit("session.start", {"goal": goal})
        return self._step()

    def resume(self, payload: dict | None = None) -> PullRequest | SessionResult:
        if self.state == State.IDLE and self._reason.startswith("budget_exceeded"):
            self.budget.turns = 0
            self.budget.tool_calls = 0
            self.budget.started_at = time.time()
            self._reason = ""
            prev = self._prev_state
            self._prev_state = None
            if not self._plan:
                return self._begin_plan()
            if prev == State.EXECUTING:
                self.state = State.EXECUTING
            else:
                self.state = State.REFLECTING
            return self._step()
        if self.state == State.AWAITING_TOOL:
            if payload is None:
                raise ValueError("resume from AWAITING_TOOL requires a payload")
            current = self._plan[self._cursor]
            if "error" in payload:
                current.error = str(payload["error"])
                self._emit("tool.error", {"step": current.id, "error": current.error})
                self.hooks.fire("on_error", {"step": current, "error": current.error})
            else:
                current.result = payload.get("result")
                self._emit("tool.result", {"step": current.id, "result": current.result})
            self.hooks.fire("after_tool_call", {"step": current})
            self._transition(State.REFLECTING)
            return self._step()
        raise RuntimeError(f"resume() unsupported from state {self.state.value}")

    def _begin_plan(self) -> PullRequest | SessionResult:
        self._transition(State.PLANNING)
        self.hooks.fire("before_plan", {"goal": self._goal, "history": list(self._history)})
        draft = self._planner(self._goal, list(self._history))
        self._emit("plan.draft", {"steps": [s.description for s in draft]})
        self.hooks.fire("after_plan", {"steps": draft})
        self._plan = draft
        self._cursor = 0
        self._emit("plan.commit", {"count": len(draft)})
        if not draft:
            return self._complete("no_plan")
        self._transition(State.EXECUTING)
        return self._step()

    def _step(self) -> PullRequest | SessionResult:
        if self.state == State.IDLE:
            return self._begin_plan()
        budget_hit = self._check_budget()
        if budget_hit is not None:
            return budget_hit
        if self.state == State.REFLECTING:
            self._cursor += 1
            self.budget.turns += 1
            if self._cursor >= len(self._plan):
                return self._complete("goal_met")
            self._transition(State.EXECUTING)
            return self._step()
        if self.state != State.EXECUTING:
            raise RuntimeError(f"_step requires EXECUTING/REFLECTING, got {self.state.value}")
        step = self._plan[self._cursor]
        self.hooks.fire("before_step", {"step": step})
        self._emit("step.start", {"step_id": step.id, "desc": step.description})
        if step.requires_tool:
            try:
                self.hooks.fire("before_tool_call", {"step": step})
            except HookAbort as exc:
                step.error = f"hook_abort:{exc}"
                self._emit("tool.error", {"step": step.id, "error": step.error})
                self.hooks.fire("on_error", {"step": step, "error": step.error})
                self._transition(State.REFLECTING)
                return self._step()
            self.budget.tool_calls += 1
            self._emit("tool.call", {"step": step.id, "tool": step.tool_name, "args": step.tool_args})
            self._transition(State.AWAITING_TOOL)
            self._emit("step.end", {"step_id": step.id, "outcome": "awaiting_tool"})
            self.hooks.fire("after_step", {"step": step, "outcome": "awaiting_tool"})
            return PullRequest(
                reason="tool_call",
                state=self.state,
                payload={"tool": step.tool_name, "args": step.tool_args, "step_id": step.id},
            )
        step.result = f"ok:{step.description}"
        self._emit("step.end", {"step_id": step.id, "outcome": "ok"})
        self.hooks.fire("after_step", {"step": step, "outcome": "ok"})
        self._transition(State.REFLECTING)
        return self._step()

    def _complete(self, reason: str) -> SessionResult:
        self._emit("session.complete", {"reason": reason})
        self.hooks.fire("on_complete", {"reason": reason})
        self._transition(State.DONE)
        self._reason = reason
        return SessionResult(state=self.state, reason=reason, steps=list(self._plan), events=list(self._events))


def _demo() -> None:
    loop = HarnessLoop()
    fired: list[str] = []
    for topic in HOOK_TOPICS:
        loop.hooks.on(topic, lambda payload, t=topic: fired.append(t))

    out = loop.run("ship the release notes")
    assert isinstance(out, PullRequest) and out.reason == "tool_call"
    out = loop.resume({"result": {"id": 42, "name": "ada"}})
    assert isinstance(out, PullRequest) and out.reason == "tool_call"
    final = loop.resume({"result": "summary text"})
    assert isinstance(final, SessionResult)
    assert final.state == State.DONE
    assert final.reason == "goal_met"

    report = {
        "events": [e.type for e in final.events],
        "hooks_fired": fired,
        "final_state": final.state.value,
        "final_reason": final.reason,
    }
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    _demo()

"""Tool registry with JSON Schema 2020-12 subset validation.

Conceptual references:
- ./docs/en.md (this lesson)
- IETF draft draft-bhutton-json-schema-2020-12 (subset: type, properties,
  required, enum, minLength, maxLength, pattern, items)
- RFC 6901 (JSON Pointer for error paths)

Stdlib only. Run: python3 code/main.py
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from typing import Any, Callable


PRIMITIVE_TYPE_MAP: dict[str, tuple[type, ...]] = {
    "string": (str,),
    "integer": (int,),
    "number": (int, float),
    "boolean": (bool,),
    "object": (dict,),
    "array": (list,),
    "null": (type(None),),
}

ALLOWED_KEYWORDS = {
    "type", "properties", "required", "enum",
    "minLength", "maxLength", "pattern", "items", "description",
}


@dataclass
class ValidationError:
    path: str
    keyword: str
    message: str

    def to_dict(self) -> dict:
        return {"path": self.path, "keyword": self.keyword, "message": self.message}


@dataclass
class Ok:
    pass


@dataclass
class ToolRecord:
    name: str
    description: str
    schema: dict
    handler: Callable[..., Any]
    idempotent: bool = False
    timeout_ms: int = 30_000


class ToolRegistry:
    """Name-keyed table of tool records with schema validation."""

    _NAME_RE = re.compile(r"^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$")

    def __init__(self) -> None:
        self._records: dict[str, ToolRecord] = {}
        self._order: list[str] = []

    def register(
        self,
        name: str,
        schema: dict,
        handler: Callable[..., Any],
        description: str = "",
        idempotent: bool = False,
        timeout_ms: int = 30_000,
        override: bool = False,
    ) -> ToolRecord:
        if not self._NAME_RE.match(name):
            raise ValueError(f"tool name {name!r} must match {self._NAME_RE.pattern}")
        if name in self._records and not override:
            raise ValueError(f"tool {name!r} already registered; pass override=True to replace")
        validate_schema_shape(schema)
        rec = ToolRecord(
            name=name, description=description, schema=schema, handler=handler,
            idempotent=idempotent, timeout_ms=timeout_ms,
        )
        if name not in self._records:
            self._order.append(name)
        self._records[name] = rec
        return rec

    def get(self, name: str) -> ToolRecord:
        if name not in self._records:
            raise KeyError(f"unknown tool {name!r}")
        return self._records[name]

    def names(self) -> list[str]:
        return list(self._order)

    def validate(self, name: str, args: Any) -> Ok | list[ValidationError]:
        rec = self.get(name)
        errors: list[ValidationError] = []
        _walk(rec.schema, args, "", errors)
        if errors:
            return errors
        return Ok()


def validate_schema_shape(schema: dict) -> None:
    """Reject schemas using keywords outside the supported subset."""
    if not isinstance(schema, dict):
        raise ValueError("schema must be a dict")
    unknown = set(schema.keys()) - ALLOWED_KEYWORDS
    if unknown:
        raise ValueError(f"unsupported schema keywords: {sorted(unknown)}")
    t = schema.get("type")
    if t is not None and t not in PRIMITIVE_TYPE_MAP:
        raise ValueError(f"unsupported type: {t!r}")
    enum_vals = schema.get("enum")
    if enum_vals is not None and not isinstance(enum_vals, list):
        raise ValueError("enum must be a list")
    min_len = schema.get("minLength")
    if min_len is not None:
        if isinstance(min_len, bool) or not isinstance(min_len, int) or min_len < 0:
            raise ValueError("minLength must be a non-negative integer")
    max_len = schema.get("maxLength")
    if max_len is not None:
        if isinstance(max_len, bool) or not isinstance(max_len, int) or max_len < 0:
            raise ValueError("maxLength must be a non-negative integer")
    if min_len is not None and max_len is not None and min_len > max_len:
        raise ValueError("minLength cannot be greater than maxLength")
    pattern = schema.get("pattern")
    if pattern is not None and not isinstance(pattern, str):
        raise ValueError("pattern must be a string")
    props = schema.get("properties")
    if props is not None:
        if not isinstance(props, dict):
            raise ValueError("properties must be a dict")
        for pname, psub in props.items():
            if not isinstance(pname, str):
                raise ValueError("property names must be strings")
            validate_schema_shape(psub)
    items = schema.get("items")
    if items is not None:
        validate_schema_shape(items)
    req = schema.get("required")
    if req is not None:
        if not isinstance(req, list) or not all(isinstance(x, str) for x in req):
            raise ValueError("required must be list[str]")


def _path(prefix: str, segment: str | int) -> str:
    seg = str(segment).replace("~", "~0").replace("/", "~1")
    return f"{prefix}/{seg}"


def _type_matches(value: Any, expected: str) -> bool:
    types = PRIMITIVE_TYPE_MAP[expected]
    if expected == "boolean":
        return isinstance(value, bool)
    if expected in ("integer", "number"):
        if isinstance(value, bool):
            return False
        return isinstance(value, types)
    return isinstance(value, types)


def _walk(schema: dict, value: Any, path: str, errs: list[ValidationError]) -> None:
    t = schema.get("type")
    if t is not None and not _type_matches(value, t):
        errs.append(ValidationError(
            path=path or "/",
            keyword="type",
            message=f"expected {t}, got {type(value).__name__}",
        ))
        return
    if "enum" in schema:
        if value not in schema["enum"]:
            errs.append(ValidationError(
                path=path or "/",
                keyword="enum",
                message=f"value {value!r} not in {schema['enum']!r}",
            ))
            return
    if t == "string":
        _check_string(schema, value, path, errs)
    elif t == "object":
        _check_object(schema, value, path, errs)
    elif t == "array":
        _check_array(schema, value, path, errs)


def _check_string(schema: dict, value: str, path: str, errs: list[ValidationError]) -> None:
    if "minLength" in schema and len(value) < schema["minLength"]:
        errs.append(ValidationError(
            path=path or "/", keyword="minLength",
            message=f"length {len(value)} < minLength {schema['minLength']}",
        ))
    if "maxLength" in schema and len(value) > schema["maxLength"]:
        errs.append(ValidationError(
            path=path or "/", keyword="maxLength",
            message=f"length {len(value)} > maxLength {schema['maxLength']}",
        ))
    if "pattern" in schema:
        try:
            if not re.search(schema["pattern"], value):
                errs.append(ValidationError(
                    path=path or "/", keyword="pattern",
                    message=f"value {value!r} does not match pattern {schema['pattern']!r}",
                ))
        except re.error as exc:
            errs.append(ValidationError(
                path=path or "/", keyword="pattern",
                message=f"invalid regex: {exc}",
            ))


def _check_object(schema: dict, value: dict, path: str, errs: list[ValidationError]) -> None:
    required = schema.get("required", [])
    for req_name in required:
        if req_name not in value:
            errs.append(ValidationError(
                path=_path(path, req_name),
                keyword="required",
                message=f"missing required property {req_name!r}",
            ))
    props = schema.get("properties", {})
    for prop_name, prop_value in value.items():
        if prop_name in props:
            _walk(props[prop_name], prop_value, _path(path, prop_name), errs)


def _check_array(schema: dict, value: list, path: str, errs: list[ValidationError]) -> None:
    items_schema = schema.get("items")
    if items_schema is None:
        return
    for idx, item in enumerate(value):
        _walk(items_schema, item, _path(path, idx), errs)


def _demo() -> None:
    registry = ToolRegistry()

    def get_user(id: int) -> dict:
        return {"id": id, "name": "ada"}

    registry.register(
        name="db.get_user",
        description="Fetch a user record by id.",
        schema={
            "type": "object",
            "required": ["id"],
            "properties": {
                "id": {"type": "integer"},
                "fields": {
                    "type": "array",
                    "items": {"type": "string", "enum": ["id", "name", "email"]},
                },
            },
        },
        handler=get_user,
        idempotent=True,
    )

    cases = [
        {"id": 42, "fields": ["id", "name"]},
        {"id": "forty-two"},
        {"fields": ["id"]},
        {"id": 1, "fields": ["id", "phone"]},
    ]
    report = []
    for c in cases:
        result = registry.validate("db.get_user", c)
        if isinstance(result, Ok):
            report.append({"args": c, "ok": True})
        else:
            report.append({"args": c, "ok": False, "errors": [e.to_dict() for e in result]})
    print(json.dumps({"tools": registry.names(), "cases": report}, indent=2))


if __name__ == "__main__":
    _demo()

"""JSON-RPC 2.0 over newline-delimited stdio.

Conceptual references:
- ./docs/en.md (this lesson)
- JSON-RPC 2.0 specification (https://www.jsonrpc.org/specification)
- RFC 8259 (JSON)

Stdlib only. Run: python3 code/main.py
"""

from __future__ import annotations

import io
import json
import sys
from dataclasses import dataclass
from typing import Any, BinaryIO, Callable, Iterable


ERR_PARSE = -32700
ERR_INVALID_REQUEST = -32600
ERR_METHOD_NOT_FOUND = -32601
ERR_INVALID_PARAMS = -32602
ERR_INTERNAL = -32603


class JsonRpcError(Exception):
    code: int = ERR_INTERNAL

    def __init__(self, message: str, data: Any | None = None) -> None:
        super().__init__(message)
        self.message = message
        self.data = data


class MethodNotFound(JsonRpcError):
    code = ERR_METHOD_NOT_FOUND


class InvalidParams(JsonRpcError):
    code = ERR_INVALID_PARAMS


@dataclass
class Request:
    method: str
    params: Any
    id: int | str | None
    is_notification: bool


def _is_valid_envelope(msg: Any) -> bool:
    if not isinstance(msg, dict):
        return False
    if msg.get("jsonrpc") != "2.0":
        return False
    if not isinstance(msg.get("method"), str):
        return False
    if "params" in msg and not isinstance(msg["params"], (dict, list)):
        return False
    if "id" in msg:
        rid = msg["id"]
        if isinstance(rid, bool):
            return False
        if not isinstance(rid, (int, str, type(None))):
            return False
    return True


def parse_request(raw: str) -> tuple[Request | None, dict | None]:
    """Parse one JSON line. Returns (Request, None) on success or (None, error_dict).

    error_dict is a JSON-RPC error response ready to write out.
    """
    try:
        msg = json.loads(raw)
    except json.JSONDecodeError as exc:
        return None, _err_envelope(None, ERR_PARSE, f"parse error: {exc}")
    if not _is_valid_envelope(msg):
        rid = msg.get("id") if isinstance(msg, dict) else None
        return None, _err_envelope(rid, ERR_INVALID_REQUEST, "invalid request envelope")
    is_notif = "id" not in msg
    return Request(
        method=msg["method"],
        params=msg.get("params"),
        id=msg.get("id"),
        is_notification=is_notif,
    ), None


def _err_envelope(rid: int | str | None, code: int, message: str, data: Any | None = None) -> dict:
    err: dict[str, Any] = {"code": code, "message": message}
    if data is not None:
        err["data"] = data
    return {"jsonrpc": "2.0", "id": rid, "error": err}


def _ok_envelope(rid: int | str | None, result: Any) -> dict:
    return {"jsonrpc": "2.0", "id": rid, "result": result}


def _notification_envelope(method: str, params: Any | None) -> dict:
    env: dict[str, Any] = {"jsonrpc": "2.0", "method": method}
    if params is not None:
        env["params"] = params
    return env


class StdioTransport:
    """Newline-delimited JSON-RPC 2.0 over a pair of byte streams."""

    def __init__(self, stdin: BinaryIO, stdout: BinaryIO) -> None:
        self._in: BinaryIO = stdin
        self._out: BinaryIO = stdout

    def read_line(self) -> bytes | None:
        line = self._in.readline()
        if not line:
            return None
        return line

    def write_response(self, rid: int | str | None, result: Any) -> None:
        self._write(_ok_envelope(rid, result))

    def write_error(self, rid: int | str | None, code: int, message: str, data: Any | None = None) -> None:
        self._write(_err_envelope(rid, code, message, data))

    def write_notification(self, method: str, params: Any | None = None) -> None:
        self._write(_notification_envelope(method, params))

    def _write(self, obj: dict) -> None:
        encoded = json.dumps(obj, separators=(",", ":"))
        self._out.write((encoded + "\n").encode("utf-8"))
        self._out.flush()


Handler = Callable[[str, Any], Any]


def _handle_one(handler: Handler, transport: StdioTransport, req: Request) -> dict | None:
    """Dispatch a single Request. Returns the response envelope (or None for notification)."""
    try:
        result = handler(req.method, req.params)
    except MethodNotFound as exc:
        return None if req.is_notification else _err_envelope(req.id, exc.code, exc.message, exc.data)
    except InvalidParams as exc:
        return None if req.is_notification else _err_envelope(req.id, exc.code, exc.message, exc.data)
    except JsonRpcError as exc:
        return None if req.is_notification else _err_envelope(req.id, exc.code, exc.message, exc.data)
    except Exception as exc:
        return None if req.is_notification else _err_envelope(
            req.id, ERR_INTERNAL, "internal error",
            {"exception": type(exc).__name__, "detail": str(exc)},
        )
    if req.is_notification:
        return None
    return _ok_envelope(req.id, result)


def _process_batch(handler: Handler, transport: StdioTransport, items: list) -> list | None:
    out: list = []
    for raw in items:
        if not isinstance(raw, dict) or not _is_valid_envelope(raw):
            rid = raw.get("id") if isinstance(raw, dict) else None
            out.append(_err_envelope(rid, ERR_INVALID_REQUEST, "invalid request envelope"))
            continue
        is_notif = "id" not in raw
        req = Request(
            method=raw["method"], params=raw.get("params"),
            id=raw.get("id"), is_notification=is_notif,
        )
        resp = _handle_one(handler, transport, req)
        if resp is not None:
            out.append(resp)
    if not out:
        return None
    return out


def _write_raw(transport: StdioTransport, obj: Any) -> None:
    encoded = json.dumps(obj, separators=(",", ":"))
    transport._out.write((encoded + "\n").encode("utf-8"))
    transport._out.flush()


def serve(handler: Handler, transport: StdioTransport) -> None:
    """Read requests from transport until EOF. Dispatch each through handler."""
    while True:
        line = transport.read_line()
        if line is None:
            return
        text = line.decode("utf-8").rstrip("\n").strip()
        if not text:
            continue
        try:
            parsed = json.loads(text)
        except json.JSONDecodeError as exc:
            transport.write_error(None, ERR_PARSE, f"parse error: {exc}")
            continue
        if isinstance(parsed, list):
            if not parsed:
                transport.write_error(None, ERR_INVALID_REQUEST, "empty batch")
                continue
            batch_out = _process_batch(handler, transport, parsed)
            if batch_out is not None:
                _write_raw(transport, batch_out)
            continue
        req, err = parse_request(text)
        if err is not None:
            _write_raw(transport, err)
            continue
        resp = _handle_one(handler, transport, req)
        if resp is not None:
            _write_raw(transport, resp)


def _demo() -> None:
    """Self-terminating demo using io.BytesIO. No process spawn."""

    def handler(method: str, params: Any) -> Any:
        if method == "math.add":
            if not isinstance(params, dict) or "a" not in params or "b" not in params:
                raise InvalidParams("a and b required")
            return params["a"] + params["b"]
        if method == "echo":
            return params
        if method == "boom":
            raise RuntimeError("intentional")
        raise MethodNotFound(f"method {method!r}")

    requests = [
        {"jsonrpc": "2.0", "id": 1, "method": "math.add", "params": {"a": 2, "b": 3}},
        {"jsonrpc": "2.0", "id": 2, "method": "math.add", "params": {"a": 5}},
        {"jsonrpc": "2.0", "id": 3, "method": "missing"},
        {"jsonrpc": "2.0", "id": 4, "method": "boom"},
        {"jsonrpc": "2.0", "method": "log", "params": {"level": "info"}},
        [
            {"jsonrpc": "2.0", "id": 10, "method": "echo", "params": {"text": "hi"}},
            {"jsonrpc": "2.0", "method": "log", "params": {"msg": "skip-me"}},
            {"jsonrpc": "2.0", "id": 11, "method": "math.add", "params": {"a": 1, "b": 1}},
        ],
    ]

    stdin = io.BytesIO()
    for r in requests:
        stdin.write((json.dumps(r) + "\n").encode("utf-8"))
    stdin.write(b"{not json\n")
    stdin.seek(0)
    stdout = io.BytesIO()
    transport = StdioTransport(stdin, stdout)
    serve(handler, transport)
    stdout.seek(0)
    lines = [json.loads(line) for line in stdout.read().decode("utf-8").splitlines() if line]
    print(json.dumps({"server_responses": lines}, indent=2))


if __name__ == "__main__":
    _demo()

"""Function call dispatcher with timeout, retry, idempotency, concurrency limit.

Conceptual references:
- ./docs/en.md (this lesson)
- JSON-RPC 2.0 specification (error envelope shape)
- IETF draft draft-bhutton-json-schema-2020-12 (schema subset reused)

Stdlib only. Run: python3 code/main.py
"""

from __future__ import annotations

import asyncio
import inspect
import json
import random
import re
import time
from dataclasses import dataclass, field
from typing import Any, Awaitable, Callable, Iterable


ERR_METHOD_NOT_FOUND = -32601
ERR_INVALID_PARAMS = -32602
ERR_INTERNAL = -32603


class TransientError(Exception):
    """Raised by a handler to indicate the failure is worth retrying."""


class _DispatchedError(Exception):
    """Internal sentinel that wraps a DispatchError so dedup followers preserve kind."""

    def __init__(self, error: "DispatchError") -> None:
        super().__init__(error.message)
        self.error = error


@dataclass
class DispatchError(Exception):
    kind: str
    message: str
    attempts: int
    jsonrpc_code: int = ERR_INTERNAL

    def __post_init__(self) -> None:
        super().__init__(f"{self.kind}: {self.message}")

    def to_envelope(self) -> dict:
        return {
            "code": self.jsonrpc_code,
            "message": self.message,
            "data": {"kind": self.kind, "attempts": self.attempts},
        }


@dataclass
class DispatchOk:
    result: Any
    attempts: int


@dataclass
class _ToolRecord:
    name: str
    schema: dict
    handler: Callable[..., Any]
    idempotent: bool = False
    timeout_ms: int = 30_000


class MiniRegistry:
    """A trimmed registry: name, schema, handler, idempotent, timeout."""

    def __init__(self) -> None:
        self._recs: dict[str, _ToolRecord] = {}

    def register(
        self, name: str, schema: dict, handler: Callable[..., Any],
        *, idempotent: bool = False, timeout_ms: int = 30_000,
    ) -> None:
        self._recs[name] = _ToolRecord(
            name=name, schema=schema, handler=handler,
            idempotent=idempotent, timeout_ms=timeout_ms,
        )

    def get(self, name: str) -> _ToolRecord:
        if name not in self._recs:
            raise KeyError(name)
        return self._recs[name]

    def validate(self, name: str, args: Any) -> list[str]:
        rec = self.get(name)
        errs: list[str] = []
        _walk(rec.schema, args, "", errs)
        return errs


def _walk(schema: dict, value: Any, path: str, errs: list[str]) -> None:
    t = schema.get("type")
    type_ok = True
    if t == "object" and not isinstance(value, dict):
        type_ok = False
    elif t == "integer" and (isinstance(value, bool) or not isinstance(value, int)):
        type_ok = False
    elif t == "string" and not isinstance(value, str):
        type_ok = False
    elif t == "array" and not isinstance(value, list):
        type_ok = False
    if not type_ok:
        errs.append(f"{path or '/'}: expected {t}, got {type(value).__name__}")
        return
    if t == "object":
        for req in schema.get("required", []):
            if req not in value:
                errs.append(f"{path}/{req}: required")
        for k, sub in schema.get("properties", {}).items():
            if k in value:
                _walk(sub, value[k], f"{path}/{k}", errs)


@dataclass
class _InFlight:
    future: asyncio.Future
    started_at: float


class Dispatcher:
    """Per-call timeout, retry, idempotency, concurrency limit."""

    def __init__(
        self,
        registry: MiniRegistry,
        *,
        max_attempts: int = 3,
        concurrency: int = 8,
        cache_ttl_seconds: float = 60.0,
        sleep: Callable[[float], Awaitable[None]] | None = None,
    ) -> None:
        if max_attempts <= 0:
            raise ValueError("max_attempts must be > 0")
        self.registry = registry
        self.max_attempts = max_attempts
        self._sem = asyncio.Semaphore(concurrency)
        self._inflight: dict[str, _InFlight] = {}
        self._cache: dict[str, tuple[Any, float]] = {}
        self._cache_ttl = cache_ttl_seconds
        self._sleep = sleep or asyncio.sleep

    async def dispatch(
        self,
        name: str,
        args: dict,
        *,
        timeout_ms_override: int | None = None,
        idempotency_key: str | None = None,
        budget_tool_calls_remaining: int | None = None,
    ) -> DispatchOk | DispatchError:
        try:
            rec = self.registry.get(name)
        except KeyError:
            return DispatchError(
                kind="not_found", message=f"tool {name!r}", attempts=0,
                jsonrpc_code=ERR_METHOD_NOT_FOUND,
            )

        errs = self.registry.validate(name, args)
        if errs:
            return DispatchError(
                kind="schema", message="; ".join(errs), attempts=0,
                jsonrpc_code=ERR_INVALID_PARAMS,
            )

        if budget_tool_calls_remaining is not None and budget_tool_calls_remaining <= 0:
            return DispatchError(
                kind="budget_exceeded", message="tool_calls remaining is 0", attempts=0,
            )

        if idempotency_key is not None:
            now = time.monotonic()
            cached = self._cache.get(idempotency_key)
            if cached is not None and now - cached[1] < self._cache_ttl:
                return DispatchOk(result=cached[0], attempts=0)
            inflight = self._inflight.get(idempotency_key)
            if inflight is not None:
                try:
                    res = await inflight.future
                    return DispatchOk(result=res, attempts=0)
                except Exception as exc:
                    return _map_exception(exc, attempts=0)

        async with self._sem:
            return await self._run_with_retries(rec, args, timeout_ms_override, idempotency_key)

    async def _run_with_retries(
        self,
        rec: _ToolRecord,
        args: dict,
        timeout_override: int | None,
        idempotency_key: str | None,
    ) -> DispatchOk | DispatchError:
        timeout_ms = timeout_override if timeout_override is not None else rec.timeout_ms
        timeout_s = timeout_ms / 1000.0
        attempt = 0
        last_error: DispatchError | None = None

        loop = asyncio.get_running_loop()
        future: asyncio.Future | None = None
        if idempotency_key is not None:
            future = loop.create_future()
            self._inflight[idempotency_key] = _InFlight(future=future, started_at=time.monotonic())

        try:
            while attempt < self.max_attempts:
                attempt += 1
                try:
                    coro = _invoke(rec.handler, args)
                    result = await asyncio.wait_for(coro, timeout=timeout_s)
                except asyncio.TimeoutError:
                    last_error = DispatchError(
                        kind="timeout",
                        message=f"timeout after {timeout_ms}ms",
                        attempts=attempt,
                    )
                    if not rec.idempotent:
                        break
                    if attempt >= self.max_attempts:
                        break
                    await self._sleep(_backoff(attempt))
                    continue
                except TransientError as exc:
                    last_error = DispatchError(
                        kind="transient", message=str(exc), attempts=attempt,
                    )
                    if attempt >= self.max_attempts:
                        break
                    await self._sleep(_backoff(attempt))
                    continue
                except Exception as exc:
                    err = _map_exception(exc, attempts=attempt)
                    if future is not None and not future.done():
                        future.set_exception(_DispatchedError(err))
                    return err
                if future is not None and not future.done():
                    future.set_result(result)
                if idempotency_key is not None:
                    self._cache[idempotency_key] = (result, time.monotonic())
                return DispatchOk(result=result, attempts=attempt)

            assert last_error is not None
            if future is not None and not future.done():
                future.set_exception(_DispatchedError(last_error))
            return last_error
        finally:
            if idempotency_key is not None:
                self._inflight.pop(idempotency_key, None)

    async def gather_bounded(self, calls: Iterable[tuple[str, dict]]) -> list[DispatchOk | DispatchError]:
        return await asyncio.gather(*(self.dispatch(n, a) for n, a in calls))


async def _invoke(handler: Callable[..., Any], args: dict) -> Any:
    if inspect.iscoroutinefunction(handler):
        return await handler(**args)
    result = handler(**args)
    if inspect.isawaitable(result):
        return await result
    return result


def _backoff(attempt: int) -> float:
    base = 0.1 * (4 ** (attempt - 1))
    return base * (1 + random.random() * 0.5)


def _map_exception(exc: Exception, attempts: int) -> DispatchError:
    if isinstance(exc, _DispatchedError):
        original = exc.error
        return DispatchError(
            kind=original.kind,
            message=original.message,
            attempts=original.attempts,
            jsonrpc_code=original.jsonrpc_code,
        )
    return DispatchError(
        kind="internal",
        message=f"{type(exc).__name__}: {exc}",
        attempts=attempts,
    )


async def _demo() -> None:
    reg = MiniRegistry()

    counter = {"a": 0, "b": 0}

    async def flaky_fetch(id: int) -> dict:
        counter["a"] += 1
        if counter["a"] < 2:
            raise TransientError("upstream not ready")
        return {"id": id, "name": "ada"}

    async def slow(n: int) -> int:
        counter["b"] += 1
        await asyncio.sleep(0.05)
        return n

    reg.register(
        "fetch_user",
        schema={"type": "object", "required": ["id"], "properties": {"id": {"type": "integer"}}},
        handler=flaky_fetch, idempotent=True, timeout_ms=200,
    )
    reg.register(
        "slow",
        schema={"type": "object", "required": ["n"], "properties": {"n": {"type": "integer"}}},
        handler=slow, idempotent=True, timeout_ms=10,
    )
    reg.register(
        "noop",
        schema={"type": "object", "properties": {}},
        handler=lambda: "ok",
    )

    disp = Dispatcher(reg, max_attempts=3, concurrency=4)

    out_retry = await disp.dispatch("fetch_user", {"id": 42})
    out_timeout = await disp.dispatch("slow", {"n": 1})
    out_schema = await disp.dispatch("fetch_user", {"id": "x"})
    out_missing = await disp.dispatch("does_not_exist", {})
    out_ok = await disp.dispatch("noop", {})

    a, b = await asyncio.gather(
        disp.dispatch("noop", {}, idempotency_key="k1"),
        disp.dispatch("noop", {}, idempotency_key="k1"),
    )
    report = {
        "retry_then_success": {
            "attempts": getattr(out_retry, "attempts", None),
            "ok": isinstance(out_retry, DispatchOk),
        },
        "timeout": {"kind": getattr(out_timeout, "kind", None)},
        "schema": {"kind": getattr(out_schema, "kind", None)},
        "missing": {"kind": getattr(out_missing, "kind", None)},
        "happy": {"result": getattr(out_ok, "result", None)},
        "idempotency_pair": [isinstance(a, DispatchOk), isinstance(b, DispatchOk)],
    }
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    asyncio.run(_demo())

"""Plan-and-execute agent with replan on failure, plan diffs, and dual budgets.

Conceptual references:
- ./docs/en.md (this lesson)
- Phase 14 lesson 01 (agent loop fundamentals)
- Phase 13 lesson 02 (tool protocols overview)

Stdlib only. Run: python3 code/main.py
"""

from __future__ import annotations

import json
import time
from dataclasses import dataclass, field
from typing import Any, Callable


@dataclass
class Step:
    id: int
    tool_name: str
    args: dict
    expected_outcome: str
    result: Any | None = None
    error: str | None = None

    def signature(self) -> tuple:
        return (self.tool_name, json.dumps(self.args, sort_keys=True))


@dataclass
class PlanDiff:
    revision: int
    removed: list[int]
    added: list[int]
    revised: list[int]

    def to_dict(self) -> dict:
        return {
            "revision": self.revision,
            "removed": list(self.removed),
            "added": list(self.added),
            "revised": list(self.revised),
        }


@dataclass
class Event:
    type: str
    payload: dict
    ts: float = field(default_factory=time.time)


@dataclass
class SessionResult:
    status: str
    reason: str
    history: list[Step]
    revisions: list[PlanDiff]
    events: list[Event]

    def to_dict(self) -> dict:
        return {
            "status": self.status,
            "reason": self.reason,
            "history": [
                {"id": s.id, "tool": s.tool_name, "args": s.args,
                 "result": s.result, "error": s.error}
                for s in self.history
            ],
            "revisions": [r.to_dict() for r in self.revisions],
            "events": [{"type": e.type, "payload": e.payload, "ts": e.ts} for e in self.events],
        }


Planner = Callable[[str, list[Step], str | None], list[Step]]
ToolExecutor = Callable[[str, dict], Any]


class ToolFailure(Exception):
    pass


def _diff_plans(old: list[Step], new: list[Step], revision: int) -> PlanDiff:
    old_ids = {s.id for s in old}
    new_ids = {s.id for s in new}
    removed = sorted(old_ids - new_ids)
    added = sorted(new_ids - old_ids)
    revised: list[int] = []
    old_by_id = {s.id: s for s in old}
    for s in new:
        if s.id in old_ids and old_by_id[s.id].signature() != s.signature():
            revised.append(s.id)
    return PlanDiff(revision=revision, removed=removed, added=added, revised=revised)


class PlanExecuteAgent:
    """Sequential plan executor with replan on failure."""

    def __init__(
        self,
        planner: Planner,
        executor: ToolExecutor,
        *,
        max_steps: int = 12,
        max_replans: int = 5,
    ) -> None:
        self._planner = planner
        self._executor = executor
        self.max_steps = max_steps
        self.max_replans = max_replans
        self._events: list[Event] = []

    def _emit(self, etype: str, payload: dict) -> None:
        self._events.append(Event(type=etype, payload=payload))

    def run(self, goal: str) -> SessionResult:
        self._events = []
        history: list[Step] = []
        revisions: list[PlanDiff] = []
        steps_taken = 0
        replans_used = 0
        last_error: str | None = None

        plan = self._planner(goal, history, None)
        self._emit("plan.commit", {"revision": 0, "steps": _summarize(plan)})

        if not plan:
            self._emit("session.complete", {"reason": "no_plan"})
            return SessionResult(
                status="failed", reason="no_plan",
                history=history, revisions=revisions, events=list(self._events),
            )

        cursor = 0
        revision = 0

        while cursor < len(plan):
            if steps_taken >= self.max_steps:
                self._emit("session.complete", {"reason": "step_budget"})
                return SessionResult(
                    status="failed", reason="step_budget",
                    history=history, revisions=revisions, events=list(self._events),
                )

            step = plan[cursor]
            self._emit("step.start", {"step_id": step.id, "tool": step.tool_name})
            try:
                step.result = self._executor(step.tool_name, step.args)
                self._emit("step.end", {"step_id": step.id, "outcome": "ok"})
                history.append(step)
                cursor += 1
                steps_taken += 1
                continue
            except Exception as exc:
                step.error = f"{type(exc).__name__}: {exc}"
                self._emit("step.end", {"step_id": step.id, "outcome": "error", "error": step.error})
                history.append(step)
                steps_taken += 1
                last_error = step.error

            if replans_used >= self.max_replans:
                self._emit("session.complete", {"reason": "replan_budget"})
                return SessionResult(
                    status="failed", reason="replan_budget",
                    history=history, revisions=revisions, events=list(self._events),
                )

            replans_used += 1
            revision += 1
            new_plan = self._planner(goal, history, last_error)
            self._emit("plan.draft", {"revision": revision, "steps": _summarize(new_plan)})
            if not new_plan:
                self._emit("session.complete", {"reason": "no_plan"})
                return SessionResult(
                    status="failed", reason="no_plan",
                    history=history, revisions=revisions, events=list(self._events),
                )
            diff = _diff_plans(plan[cursor:], new_plan, revision)
            revisions.append(diff)
            self._emit("plan.diff", diff.to_dict())
            plan = new_plan
            cursor = 0
            self._emit("plan.commit", {"revision": revision, "steps": _summarize(plan)})

        self._emit("session.complete", {"reason": "goal_met"})
        return SessionResult(
            status="completed", reason="goal_met",
            history=history, revisions=revisions, events=list(self._events),
        )


def _summarize(plan: list[Step]) -> list[dict]:
    return [{"id": s.id, "tool": s.tool_name, "outcome": s.expected_outcome} for s in plan]


def make_deterministic_planner(fail_step_id: int | None, recovery: str = "route_around") -> Planner:
    """Planner used in the demo and tests.

    When ``fail_step_id`` is given, the planner inserts a ``_force_fail`` marker
    into that step's args on the initial plan. Executors that honor the marker
    raise on that step, exercising the replan path. The marker is removed on the
    revised plan so the route-around can succeed.
    """

    def planner(goal: str, history: list[Step], last_error: str | None) -> list[Step]:
        if last_error is None:
            initial = [
                Step(1, "fetch", {"key": "input"}, "loaded user input"),
                Step(2, "transform", {"mode": "v1"}, "computed v1 form"),
                Step(3, "render", {}, "rendered output"),
                Step(4, "submit", {}, "submitted to backend"),
            ]
            if fail_step_id is not None:
                for s in initial:
                    if s.id == fail_step_id:
                        s.args = {**s.args, "_force_fail": True}
            return initial
        if recovery == "route_around" and "transform" in last_error:
            return [
                Step(2, "transform", {"mode": "v2"}, "computed via fallback"),
                Step(3, "render", {}, "rendered output"),
                Step(4, "submit", {}, "submitted to backend"),
            ]
        if recovery == "give_up":
            return [
                Step(98, "log_failure", {"why": last_error or ""}, "logged failure"),
                Step(99, "notify_user", {}, "told the user"),
            ]
        return []

    return planner


def _demo() -> None:
    counters = {"transform_v1_calls": 0}

    def executor(tool: str, args: dict) -> Any:
        if args.get("_force_fail"):
            counters["transform_v1_calls"] += 1
            raise ToolFailure(f"{tool} marker-forced failure")
        if tool == "fetch":
            return {"k": "v"}
        if tool == "transform":
            if args.get("mode") == "v1":
                counters["transform_v1_calls"] += 1
                raise ToolFailure("transform v1 backend down")
            return {"ok": True}
        if tool == "render":
            return "html"
        if tool == "submit":
            return {"id": 1}
        if tool in ("log_failure", "notify_user"):
            return "logged"
        raise ToolFailure(f"unknown tool {tool}")

    agent = PlanExecuteAgent(
        planner=make_deterministic_planner(fail_step_id=2, recovery="route_around"),
        executor=executor,
        max_steps=12, max_replans=5,
    )
    res = agent.run("ship the report")
    print(json.dumps({
        "status": res.status,
        "reason": res.reason,
        "history": [(s.id, s.tool_name, bool(s.error)) for s in res.history],
        "revisions": [r.to_dict() for r in res.revisions],
        "events": [e.type for e in res.events],
        "transform_v1_calls": counters["transform_v1_calls"],
    }, indent=2))


if __name__ == "__main__":
    _demo()

"""
Verification gates and observation budget for an agent harness.

See: phases/19-capstone-projects/25-verification-gates-observation-budget/docs/en.md
Concept refs:
  - Gate-chain pattern (cheapest deny first, allow last).
  - Observation budget as a deterministic stopping criterion.
The demo at the bottom runs a synthetic three-turn loop and exits zero.
"""

from __future__ import annotations

import json
import re
import sys
from dataclasses import dataclass, field
from typing import Callable, Iterable, Protocol


# ---------------------------------------------------------------------------
# Wire shapes
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class ToolCall:
    """A request from the model to invoke a tool."""

    turn: int
    tool: str
    argv: tuple[str, ...]
    payload: str = ""

    def to_dict(self) -> dict:
        return {
            "turn": self.turn,
            "tool": self.tool,
            "argv": list(self.argv),
            "payload": self.payload,
        }


@dataclass(frozen=True)
class Observation:
    """The text the model is shown after a tool call."""

    turn: int
    tool: str
    text: str
    tokens: int

    def to_dict(self) -> dict:
        return {
            "turn": self.turn,
            "tool": self.tool,
            "tokens": self.tokens,
        }


@dataclass(frozen=True)
class GateDecision:
    """A single gate's verdict."""

    allow: bool
    gate: str
    reason: str

    def to_dict(self) -> dict:
        return {"allow": self.allow, "gate": self.gate, "reason": self.reason}


# ---------------------------------------------------------------------------
# Token estimator
# ---------------------------------------------------------------------------


def estimate_tokens(text: str) -> int:
    """A deterministic, conservative stand-in for a real tokenizer.

    Real harnesses plug in tiktoken or the model's own tokenizer.
    The gate chain only cares that the counter is monotonic and deterministic.
    """

    if not text:
        return 0
    return max(1, len(text) // 4)


# ---------------------------------------------------------------------------
# Observation ledger
# ---------------------------------------------------------------------------


@dataclass
class ObservationLedger:
    """Append-only ledger of every observation the model has been shown."""

    rows: list[Observation] = field(default_factory=list)

    def record(self, obs: Observation) -> None:
        self.rows.append(obs)

    def cumulative(self) -> int:
        return sum(row.tokens for row in self.rows)

    def per_tool(self, name: str) -> int:
        return sum(row.tokens for row in self.rows if row.tool == name)

    def turns_seen(self) -> list[int]:
        return sorted({row.turn for row in self.rows})

    def latest_turn(self) -> int:
        return self.rows[-1].turn if self.rows else -1

    def snapshot(self) -> list[dict]:
        return [row.to_dict() for row in self.rows]


# ---------------------------------------------------------------------------
# Gate protocol
# ---------------------------------------------------------------------------


@dataclass
class GateContext:
    """Read-only context passed to every gate."""

    ledger: ObservationLedger
    current_turn: int
    history: tuple[ToolCall, ...] = ()


class VerificationGate(Protocol):
    name: str

    def evaluate(self, call: ToolCall, ctx: GateContext) -> GateDecision: ...


# ---------------------------------------------------------------------------
# Concrete gates
# ---------------------------------------------------------------------------


@dataclass
class WhitelistGate:
    """Refuse any tool not in the explicit allow-set. Cheapest gate."""

    allowed: frozenset[str]
    name: str = "whitelist"

    def evaluate(self, call: ToolCall, ctx: GateContext) -> GateDecision:
        if call.tool in self.allowed:
            return GateDecision(True, self.name, "tool in allow-set")
        return GateDecision(
            False,
            self.name,
            f"tool {call.tool!r} not in allow-set {sorted(self.allowed)}",
        )


@dataclass
class RegexGate:
    """Refuse a call whose argv joins to a string matching any refuse pattern."""

    refuse_patterns: tuple[re.Pattern[str], ...]
    name: str = "regex"

    @classmethod
    def from_strings(cls, patterns: Iterable[str], name: str = "regex") -> "RegexGate":
        compiled = tuple(re.compile(p) for p in patterns)
        return cls(refuse_patterns=compiled, name=name)

    def evaluate(self, call: ToolCall, ctx: GateContext) -> GateDecision:
        haystack = " ".join(call.argv) + " " + call.payload
        for pat in self.refuse_patterns:
            if pat.search(haystack):
                return GateDecision(
                    False, self.name, f"argv matched refuse pattern {pat.pattern!r}"
                )
        return GateDecision(True, self.name, "no refuse pattern matched")


@dataclass
class RecencyGate:
    """Refuse a call if the last observation is more than window turns old.

    The intent is to force a fresh read instead of relying on stale state.
    The first call in a session always passes.
    """

    window: int
    name: str = "recency"

    def evaluate(self, call: ToolCall, ctx: GateContext) -> GateDecision:
        last = ctx.ledger.latest_turn()
        if last < 0:
            return GateDecision(True, self.name, "no prior observations")
        gap = call.turn - last
        if gap > self.window:
            return GateDecision(
                False,
                self.name,
                f"observation gap {gap} turns exceeds window {self.window}",
            )
        return GateDecision(True, self.name, f"gap {gap} within window {self.window}")


@dataclass
class BudgetGate:
    """Refuse a call once the cumulative observation budget is exhausted.

    A single call cannot in advance know how many tokens its result will be.
    The gate is therefore evaluated against the ledger as it stands before the
    call, and the harness re-runs the cumulative check against the new ledger
    state after recording the observation.
    """

    max_tokens: int
    name: str = "budget"

    def evaluate(self, call: ToolCall, ctx: GateContext) -> GateDecision:
        used = ctx.ledger.cumulative()
        if used >= self.max_tokens:
            return GateDecision(
                False,
                self.name,
                f"observation budget exhausted: {used}/{self.max_tokens} tokens",
            )
        remaining = self.max_tokens - used
        return GateDecision(
            True, self.name, f"{remaining} tokens of budget remaining"
        )


@dataclass
class PerToolBudgetGate:
    """Optional gate: refuse if a single tool has consumed more than its share."""

    limits: dict[str, int]
    name: str = "per-tool-budget"

    def evaluate(self, call: ToolCall, ctx: GateContext) -> GateDecision:
        limit = self.limits.get(call.tool)
        if limit is None:
            return GateDecision(True, self.name, "tool has no per-tool budget")
        used = ctx.ledger.per_tool(call.tool)
        if used >= limit:
            return GateDecision(
                False,
                self.name,
                f"per-tool budget for {call.tool} exhausted: {used}/{limit}",
            )
        return GateDecision(
            True, self.name, f"per-tool {call.tool}: {limit - used} tokens remaining"
        )


# ---------------------------------------------------------------------------
# Gate chain
# ---------------------------------------------------------------------------


@dataclass
class ChainOutcome:
    """The full result of a chain evaluation: the per-gate decisions plus a final verdict."""

    decisions: list[GateDecision]

    @property
    def allow(self) -> bool:
        return all(d.allow for d in self.decisions)

    @property
    def deny_reason(self) -> str | None:
        for d in self.decisions:
            if not d.allow:
                return f"[{d.gate}] {d.reason}"
        return None

    def to_dict(self) -> dict:
        return {
            "allow": self.allow,
            "deny_reason": self.deny_reason,
            "decisions": [d.to_dict() for d in self.decisions],
        }


@dataclass
class GateChain:
    """Ordered list of gates evaluated with short-circuit on first deny."""

    gates: tuple[VerificationGate, ...]

    def evaluate(self, call: ToolCall, ctx: GateContext) -> ChainOutcome:
        decisions: list[GateDecision] = []
        for gate in self.gates:
            decision = gate.evaluate(call, ctx)
            decisions.append(decision)
            if not decision.allow:
                return ChainOutcome(decisions=decisions)
        return ChainOutcome(decisions=decisions)


# ---------------------------------------------------------------------------
# Mini synthetic agent loop for the demo
# ---------------------------------------------------------------------------


ToolFn = Callable[[ToolCall], str]


@dataclass
class LoopReport:
    """Audit record of a synthetic loop run."""

    turns: int
    allowed: int
    refused: int
    observations: list[Observation]
    decisions: list[ChainOutcome]

    def to_dict(self) -> dict:
        return {
            "turns": self.turns,
            "allowed": self.allowed,
            "refused": self.refused,
            "observations": [o.to_dict() for o in self.observations],
            "decisions": [d.to_dict() for d in self.decisions],
        }


def run_synthetic_loop(
    calls: list[ToolCall],
    chain: GateChain,
    tool_fns: dict[str, ToolFn],
) -> LoopReport:
    """Run a fixed sequence of tool calls through the chain.

    This is the harness skeleton in miniature. A real harness would consult
    the model for the next tool call; the gate-chain contract is identical.
    """

    ledger = ObservationLedger()
    decisions: list[ChainOutcome] = []
    observations: list[Observation] = []
    allowed = 0
    refused = 0

    history: list[ToolCall] = []

    for call in calls:
        ctx = GateContext(
            ledger=ledger, current_turn=call.turn, history=tuple(history)
        )
        outcome = chain.evaluate(call, ctx)
        decisions.append(outcome)
        history.append(call)
        if not outcome.allow:
            refused += 1
            continue
        fn = tool_fns.get(call.tool)
        if fn is None:
            refused += 1
            continue
        result = fn(call)
        obs = Observation(
            turn=call.turn,
            tool=call.tool,
            text=result,
            tokens=estimate_tokens(result),
        )
        ledger.record(obs)
        observations.append(obs)
        allowed += 1

    return LoopReport(
        turns=len(calls),
        allowed=allowed,
        refused=refused,
        observations=observations,
        decisions=decisions,
    )


# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------


def _demo_tools() -> dict[str, ToolFn]:
    """Three synthetic tools. read_file is verbose, list_dir is small, run_tests is structured."""

    def read_file(call: ToolCall) -> str:
        target = call.argv[0] if call.argv else "<missing>"
        return (
            f"# fake contents of {target}\n"
            + ("line of fake source code that is sixty bytes long " * 12)
        )

    def list_dir(call: ToolCall) -> str:
        return "main.py\nREADME.md\ntests/test_main.py\n"

    def run_tests(call: ToolCall) -> str:
        return json.dumps(
            {"status": "passed", "tests": 4, "duration_ms": 42}, indent=2
        )

    return {"read_file": read_file, "list_dir": list_dir, "run_tests": run_tests}


def build_default_chain(budget: int = 200) -> GateChain:
    """Wire the canonical four-gate chain in the order documented in en.md."""

    return GateChain(
        gates=(
            WhitelistGate(
                allowed=frozenset({"read_file", "list_dir", "run_tests"})
            ),
            RegexGate.from_strings(
                patterns=(
                    r"\brm\s+-rf\b",
                    r"\bsudo\b",
                    r"^/etc/",
                )
            ),
            RecencyGate(window=3),
            BudgetGate(max_tokens=budget),
        )
    )


def run_demo() -> int:
    """Self-terminating demo. Prints a JSON trace and exits zero."""

    chain = build_default_chain(budget=200)
    tools = _demo_tools()

    calls = [
        ToolCall(turn=1, tool="list_dir", argv=("./",)),
        ToolCall(turn=2, tool="read_file", argv=("main.py",)),
        ToolCall(turn=3, tool="read_file", argv=("README.md",)),
        ToolCall(turn=4, tool="run_tests", argv=("./",)),
        ToolCall(turn=5, tool="shell", argv=("rm", "-rf", "/")),
    ]

    report = run_synthetic_loop(calls, chain, tools)

    print("VERIFICATION GATE DEMO")
    print(f"turns={report.turns} allowed={report.allowed} refused={report.refused}")
    print("")
    for idx, (call, outcome) in enumerate(zip(calls, report.decisions)):
        verdict = "ALLOW" if outcome.allow else "DENY"
        print(f"  [{idx}] turn={call.turn} tool={call.tool} -> {verdict}")
        if not outcome.allow:
            print(f"        reason: {outcome.deny_reason}")
    print("")
    print(f"cumulative tokens observed: {sum(o.tokens for o in report.observations)}")
    print(f"observations recorded: {len(report.observations)}")

    if report.refused < 1:
        print("ERROR: demo expected at least one refusal", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(run_demo())

