def run_demo() -> int:
    repo = prepare_scratch_repo()
    print("END-TO-END CODING AGENT DEMO")
    print(f"scratch repo: {repo}")
    print("")

    chain = build_default_chain(budget=8000)
    sandbox = Sandbox(project_root=repo, timeout_seconds=10.0)
    metrics = MetricsRegistry()
    in_mem = InMemoryExporter()
    traces_path = os.path.join(repo, "traces.jsonl")
    jsonl = JSONLExporter(path=traces_path)
    builder = SpanBuilder(exporters=[in_mem, jsonl], metrics=metrics)

    runner = AgentRun(
        repo_root=repo,
        chain=chain,
        sandbox=sandbox,
        builder=builder,
        observation_budget=8000,
        step_budget=12,
    )
    report = runner.run()
    jsonl.close()

    print(f"solved={report.solved} halted={report.halted_reason}")
    print(
        f"steps={len(report.steps)} obs_tokens={report.observation_tokens}/"
        f"{report.max_observation_budget} refused_legal={report.refused_legal_tool_calls}"
    )
    print("")
    print("steps:")
    for step in report.steps:
        verdict = "ok" if step.allow and step.exit_code == 0 else f"exit={step.exit_code}"
        print(
            f"  [{step.index}] {step.state:10s} {step.tool:11s} "
            f"argv={list(step.argv)} -> {verdict}"
        )

    print("")
    print(f"spans emitted: {len(in_mem.spans)} (jsonl at {traces_path})")
    print("")
    print("--- prometheus exposition (excerpt) ---")
    text = prometheus_text(metrics)
    # Print only the counter + the tool_latency_ms count lines for brevity.
    excerpt: list[str] = []
    for line in text.splitlines():
        if (
            line.startswith("tools_called_total")
            or line.startswith("# TYPE tools_called_total")
            or line.startswith("# TYPE tool_latency_ms")
            or "tool_latency_ms_count" in line
            or "tool_latency_ms_sum" in line
        ):
            excerpt.append(line)
    print("\n".join(excerpt))

    # Hard assertions for the demo: the lesson promises them.
    if not report.solved:
        print(f"ERROR: agent did not solve fixture: {report.halted_reason}", file=sys.stderr)
        return 1
    if len(report.steps) >= 12:
        print(f"ERROR: agent used too many steps: {len(report.steps)}", file=sys.stderr)
        return 1
    if report.observation_tokens > report.max_observation_budget:
        print("ERROR: observation budget exceeded", file=sys.stderr)
        return 1
    if report.refused_legal_tool_calls != 0:
        print("ERROR: agent fired denied tool calls", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(run_demo())

"""Language model evaluation harness from scratch.

Task spec is a JSONL line per example with `prompt`, `targets`, and
`metric`. Five metrics ship: exact match for arithmetic, rouge-l F1 for
summary, executable check for code, accuracy for multiple choice, and
substring contains for generation. The runner batches examples by task,
runs them against a swappable model adapter, and emits a leaderboard
JSON with per-task and overall scores.

The model adapter is the seam. The default adapter is a deterministic
toy that pattern-matches the prompt; it has just enough behavior to make
the harness's scoring code exercise every metric. Swap the adapter for
an HTTP client, a local inference call, or a mock in tests.

Run: python3 code/main.py
"""

from __future__ import annotations

import argparse
import ast
import json
import operator
import re
import sys
import textwrap
import time
from collections import Counter
from dataclasses import dataclass, field, asdict
from pathlib import Path
from typing import Callable, Dict, Iterable, List, Optional, Protocol, Sequence


HERE = Path(__file__).parent
OUT_DIR = HERE.parent / "outputs"
TASKS_DIR = OUT_DIR / "tasks"
LEADERBOARD = OUT_DIR / "leaderboard.json"


@dataclass
class Example:
    id: str
    prompt: str
    targets: List[str]
    metric: str
    extras: Dict[str, object] = field(default_factory=dict)


@dataclass
class TaskResult:
    task: str
    metric: str
    score: float
    correct: int
    total: int
    per_example: List[Dict[str, object]] = field(default_factory=list)
    latency_ms: float = 0.0


@dataclass
class Leaderboard:
    schema: str
    timestamp: float
    overall_score: float
    tasks: List[TaskResult]


class ModelAdapter(Protocol):
    def generate(self, prompts: Sequence[str]) -> List[str]:
        ...

    @property
    def name(self) -> str:
        ...


class ToyAdapter:
    """Deterministic adapter that pattern-matches each task.

    The point is not to score well; the point is to give the harness a
    fixed set of outputs to score against. Replace with a real client
    when you ship the harness against a model.
    """

    name = "toy.v1"

    def generate(self, prompts: Sequence[str]) -> List[str]:
        return [self._answer(p) for p in prompts]

    def _answer(self, prompt: str) -> str:
        text = prompt.strip()
        if text.startswith("compute:"):
            expr = text[len("compute:"):].strip()
            try:
                return str(safe_arith_eval(expr))
            except Exception:
                return ""
        if text.startswith("summarize:"):
            body = text[len("summarize:"):].strip()
            sentences = re.split(r"(?<=[.!?])\s+", body)
            return sentences[0] if sentences else body
        if text.startswith("python:"):
            body = text[len("python:"):].strip()
            if "double" in body:
                return "def f(x):\n    return x * 2\n"
            if "increment" in body:
                return "def f(x):\n    return x + 1\n"
            if "square" in body:
                return "def f(x):\n    return x * x\n"
            return "def f(x):\n    return x\n"
        if text.startswith("choose:"):
            body = text[len("choose:"):].strip()
            return body.split("|", 1)[0].strip()[:1].upper()
        if text.startswith("write:"):
            body = text[len("write:"):].strip()
            return body
        return text


_ARITH_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Pow: operator.pow,
}


def safe_arith_eval(expr: str) -> float:
    """Evaluate a small arithmetic expression without exposing eval."""
    tree = ast.parse(expr, mode="eval")
    return _safe_eval(tree.body)


def _safe_eval(node: ast.AST) -> float:
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in _ARITH_OPS:
        return _ARITH_OPS[type(node.op)](_safe_eval(node.left), _safe_eval(node.right))
    if isinstance(node, ast.UnaryOp) and type(node.op) in _ARITH_OPS:
        return _ARITH_OPS[type(node.op)](_safe_eval(node.operand))
    raise ValueError(f"unsafe node: {ast.dump(node)}")


def normalize(s: str) -> str:
    return re.sub(r"\s+", " ", s.strip().lower())


def metric_exact_match(prediction: str, targets: List[str]) -> float:
    norm_pred = normalize(prediction)
    return 1.0 if any(normalize(t) == norm_pred for t in targets) else 0.0


def metric_substring_contains(prediction: str, targets: List[str]) -> float:
    norm_pred = normalize(prediction)
    return 1.0 if any(normalize(t) in norm_pred for t in targets) else 0.0


def metric_multiple_choice(prediction: str, targets: List[str]) -> float:
    pred = prediction.strip()[:1].upper()
    return 1.0 if pred in {t.strip()[:1].upper() for t in targets} else 0.0


def _tokens(s: str) -> List[str]:
    return re.findall(r"[a-z0-9]+", s.lower())


def _lcs_length(a: List[str], b: List[str]) -> int:
    if not a or not b:
        return 0
    prev = [0] * (len(b) + 1)
    for ai in a:
        cur = [0] * (len(b) + 1)
        for j, bj in enumerate(b):
            if ai == bj:
                cur[j + 1] = prev[j] + 1
            else:
                cur[j + 1] = max(prev[j + 1], cur[j])
        prev = cur
    return prev[-1]


def metric_rouge_l(prediction: str, targets: List[str]) -> float:
    pred = _tokens(prediction)
    if not pred:
        return 0.0
    best = 0.0
    for ref in targets:
        ref_toks = _tokens(ref)
        if not ref_toks:
            continue
        lcs = _lcs_length(pred, ref_toks)
        if lcs == 0:
            continue
        prec = lcs / len(pred)
        rec = lcs / len(ref_toks)
        if prec + rec == 0:
            continue
        f1 = 2 * prec * rec / (prec + rec)
        if f1 > best:
            best = f1
    return best


def metric_code_exec(prediction: str, targets: List[str], extras: Dict[str, object]) -> float:
    """Execute the prediction in a small namespace and compare against
    expected outputs.

    Targets is a list of stringified expected results; extras carries a
    list of (input, output) pairs the function is checked against. The
    code runs in a stripped builtins namespace so it cannot reach the
    filesystem or network.
    """
    pairs = extras.get("io_pairs") or []
    if not isinstance(pairs, list) or not pairs:
        return 0.0
    safe_globals = {"__builtins__": {"range": range, "len": len, "min": min, "max": max, "abs": abs, "int": int, "float": float}}
    local: Dict[str, object] = {}
    try:
        exec(prediction, safe_globals, local)
    except Exception:
        return 0.0
    fn = local.get("f")
    if not callable(fn):
        return 0.0
    correct = 0
    for pair in pairs:
        if not (isinstance(pair, list) and len(pair) == 2):
            continue
        x, expected = pair
        try:
            actual = fn(x)
        except Exception:
            continue
        if actual == expected:
            correct += 1
    if not pairs:
        return 0.0
    return correct / len(pairs)


METRIC_FNS: Dict[str, Callable[..., float]] = {
    "exact_match": lambda p, t, e: metric_exact_match(p, t),
    "substring_contains": lambda p, t, e: metric_substring_contains(p, t),
    "multiple_choice": lambda p, t, e: metric_multiple_choice(p, t),
    "rouge_l": lambda p, t, e: metric_rouge_l(p, t),
    "code_exec": lambda p, t, e: metric_code_exec(p, t, e),
}


def load_task_jsonl(path: Path) -> List[Example]:
    examples: List[Example] = []
    with path.open("r", encoding="utf-8") as f:
        for line_num, raw in enumerate(f, start=1):
            raw = raw.strip()
            if not raw or raw.startswith("#"):
                continue
            try:
                obj = json.loads(raw)
            except json.JSONDecodeError as exc:
                raise ValueError(f"bad json at {path}:{line_num}: {exc}") from exc
            examples.append(Example(
                id=str(obj.get("id", f"ex-{line_num}")),
                prompt=obj["prompt"],
                targets=list(obj["targets"]),
                metric=obj["metric"],
                extras=dict(obj.get("extras", {})),
            ))
    return examples


def write_task_jsonl(examples: Iterable[Example], path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as f:
        for ex in examples:
            f.write(json.dumps({
                "id": ex.id,
                "prompt": ex.prompt,
                "targets": ex.targets,
                "metric": ex.metric,
                **({"extras": ex.extras} if ex.extras else {}),
            }) + "\n")


def run_task(
    task_name: str,
    examples: List[Example],
    adapter: ModelAdapter,
    *,
    batch_size: int = 8,
) -> TaskResult:
    if batch_size <= 0:
        raise ValueError(f"batch_size must be > 0, got {batch_size}")
    if not examples:
        return TaskResult(task=task_name, metric="none", score=0.0, correct=0, total=0)
    metric = examples[0].metric
    assert all(ex.metric == metric for ex in examples), f"task {task_name} mixes metrics"
    metric_fn = METRIC_FNS[metric]
    per_example: List[Dict[str, object]] = []
    correct_sum = 0.0
    total = 0
    start = time.perf_counter()
    for i in range(0, len(examples), batch_size):
        chunk = examples[i:i + batch_size]
        prompts = [ex.prompt for ex in chunk]
        outputs = adapter.generate(prompts)
        if len(outputs) != len(chunk):
            raise ValueError(
                f"adapter returned {len(outputs)} outputs for {len(chunk)} prompts in task {task_name}"
            )
        for ex, out in zip(chunk, outputs, strict=True):
            score = metric_fn(out, ex.targets, ex.extras)
            correct_sum += score
            total += 1
            per_example.append({
                "id": ex.id,
                "prompt": ex.prompt,
                "prediction": out,
                "targets": ex.targets,
                "score": score,
            })
    latency_ms = (time.perf_counter() - start) * 1000.0
    score = correct_sum / total if total else 0.0
    correct_int = int(round(correct_sum))
    return TaskResult(
        task=task_name,
        metric=metric,
        score=score,
        correct=correct_int,
        total=total,
        per_example=per_example,
        latency_ms=latency_ms,
    )


def run_leaderboard(
    tasks: Dict[str, List[Example]],
    adapter: ModelAdapter,
    *,
    batch_size: int = 8,
) -> Leaderboard:
    results: List[TaskResult] = []
    for name in sorted(tasks):
        result = run_task(name, tasks[name], adapter, batch_size=batch_size)
        results.append(result)
    if results:
        overall = sum(r.score for r in results) / len(results)
    else:
        overall = 0.0
    return Leaderboard(
        schema="leaderboard.v1",
        timestamp=time.time(),
        overall_score=overall,
        tasks=results,
    )


def write_leaderboard(
    board: Leaderboard,
    path: Path,
    *,
    adapter_name: str,
    include_per_example: bool = False,
) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        "schema": board.schema,
        "timestamp": board.timestamp,
        "overall_score": board.overall_score,
        "adapter": adapter_name,
        "tasks": [
            {
                "task": r.task,
                "metric": r.metric,
                "score": r.score,
                "correct": r.correct,
                "total": r.total,
                "latency_ms": r.latency_ms,
                **({"per_example": r.per_example} if include_per_example else {}),
            }
            for r in board.tasks
        ],
    }
    path.write_text(json.dumps(payload, indent=2) + "\n")


def build_arithmetic_task() -> List[Example]:
    items = [("2 + 2", "4"), ("7 - 3", "4"), ("6 * 4", "24"), ("100 / 4", "25.0"), ("12 + 9", "21")]
    return [Example(id=f"arith-{i:02d}", prompt=f"compute: {q}", targets=[a], metric="exact_match") for i, (q, a) in enumerate(items)]


def build_summary_task() -> List[Example]:
    items = [
        ("Cats are mammals. Mammals are warm blooded.", "cats are mammals"),
        ("Python uses indentation. Indentation defines blocks.", "python uses indentation"),
        ("The river flows east. Boats pass slowly.", "the river flows east"),
        ("Storms approach the coast. Waves rise quickly.", "storms approach the coast"),
        ("Bread bakes at high heat. Crust forms last.", "bread bakes at high heat"),
    ]
    return [Example(id=f"sum-{i:02d}", prompt=f"summarize: {p}", targets=[t], metric="rouge_l") for i, (p, t) in enumerate(items)]


def build_code_task() -> List[Example]:
    items = [
        ("write a function f that doubles its input", "double", [[1, 2], [3, 6], [5, 10]]),
        ("write a function f that increments its input", "increment", [[1, 2], [5, 6], [10, 11]]),
        ("write a function f that squares its input", "square", [[2, 4], [3, 9], [4, 16]]),
        ("write a function f that doubles its input again", "double", [[7, 14], [9, 18]]),
        ("write a function f that increments its input again", "increment", [[0, 1], [2, 3]]),
    ]
    return [
        Example(
            id=f"code-{i:02d}",
            prompt=f"python: {prompt}",
            targets=["ok"],
            metric="code_exec",
            extras={"io_pairs": pairs, "tag": tag},
        )
        for i, (prompt, tag, pairs) in enumerate(items)
    ]


def build_choice_task() -> List[Example]:
    items = [
        ("A | mammal, B | reptile, C | bird", ["A"]),
        ("A | apple, B | car, C | tree", ["A"]),
        ("A | water, B | iron, C | wood", ["A"]),
        ("A | square, B | triangle, C | circle", ["A"]),
        ("A | bread, B | rock, C | leaf", ["A"]),
    ]
    return [Example(id=f"mc-{i:02d}", prompt=f"choose: {q}", targets=t, metric="multiple_choice") for i, (q, t) in enumerate(items)]


def build_generation_task() -> List[Example]:
    items = [
        ("hello world", ["hello"]),
        ("training language models", ["language"]),
        ("evaluation harness", ["evaluation"]),
        ("gradient accumulation step", ["gradient"]),
        ("distributed parameter sharding", ["distributed"]),
    ]
    return [Example(id=f"gen-{i:02d}", prompt=f"write: {p}", targets=t, metric="substring_contains") for i, (p, t) in enumerate(items)]


def seed_fixture_tasks(target_dir: Path) -> Dict[str, Path]:
    target_dir.mkdir(parents=True, exist_ok=True)
    tasks = {
        "arithmetic": build_arithmetic_task(),
        "summary": build_summary_task(),
        "code-exec": build_code_task(),
        "multiple-choice": build_choice_task(),
        "generation": build_generation_task(),
    }
    paths: Dict[str, Path] = {}
    for name, examples in tasks.items():
        path = target_dir / f"{name}.jsonl"
        write_task_jsonl(examples, path)
        paths[name] = path
    return paths


def load_all_tasks(task_dir: Path) -> Dict[str, List[Example]]:
    tasks: Dict[str, List[Example]] = {}
    for path in sorted(task_dir.glob("*.jsonl")):
        tasks[path.stem] = load_task_jsonl(path)
    return tasks


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser()
    p.add_argument("--task-dir", type=Path, default=TASKS_DIR)
    p.add_argument("--out", type=Path, default=LEADERBOARD)
    p.add_argument("--batch-size", type=int, default=4)
    p.add_argument("--include-per-example", action="store_true")
    p.add_argument("--seed-fixtures", action="store_true")
    return p.parse_args()


def main() -> int:
    args = parse_args()
    if args.seed_fixtures or not args.task_dir.exists() or not list(args.task_dir.glob("*.jsonl")):
        print(f"seeding fixture tasks into {args.task_dir}")
        seed_fixture_tasks(args.task_dir)
    tasks = load_all_tasks(args.task_dir)
    print(f"loaded {len(tasks)} tasks: {sorted(tasks)}")
    adapter = ToyAdapter()
    board = run_leaderboard(tasks, adapter, batch_size=args.batch_size)
    write_leaderboard(
        board,
        args.out,
        adapter_name=adapter.name,
        include_per_example=args.include_per_example,
    )
    print(f"overall_score = {board.overall_score:.3f}")
    for r in board.tasks:
        print(f"  {r.task:>16}  metric={r.metric:>18}  score={r.score:0.3f}  ({r.correct}/{r.total})  latency_ms={r.latency_ms:.1f}")
    print(f"wrote {args.out}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Literature retrieval: BM25 over abstracts plus citation graph traversal, merged.

Conceptual references:
- ./docs/en.md (this lesson)
- Phase 19 Track A lessons 20-29 (agent harness primitives)

Stdlib only. Run: python3 code/main.py
"""

from __future__ import annotations

import json
import math
import re
import time
from collections import Counter, defaultdict, deque
from dataclasses import dataclass, field


TOKEN_RE = re.compile(r"[a-z0-9]+")


@dataclass
class Paper:
    id: str
    title: str
    abstract: str
    year: int
    authors: list[str]
    references: list[str] = field(default_factory=list)
    citations: list[str] = field(default_factory=list)
    source: str = "merged"

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "title": self.title,
            "year": self.year,
            "authors": list(self.authors),
            "references": list(self.references),
            "citations": list(self.citations),
            "source": self.source,
        }


def tokenise(text: str) -> list[str]:
    return TOKEN_RE.findall(text.lower())


class BM25Index:
    """Okapi BM25 with default k1=1.5, b=0.75. Stdlib only."""

    def __init__(self, k1: float = 1.5, b: float = 0.75) -> None:
        self.k1 = k1
        self.b = b
        self._doc_lens: dict[str, int] = {}
        self._term_freq: dict[str, dict[str, int]] = defaultdict(dict)
        self._doc_freq: Counter = Counter()
        self._avgdl: float = 0.0
        self._n_docs: int = 0

    def add(self, doc_id: str, text: str) -> None:
        tokens = tokenise(text)
        self._doc_lens[doc_id] = len(tokens)
        counts = Counter(tokens)
        for term, count in counts.items():
            self._term_freq[term][doc_id] = count
            self._doc_freq[term] += 1
        self._n_docs += 1

    def finalise(self) -> None:
        if self._n_docs == 0:
            self._avgdl = 0.0
            return
        self._avgdl = sum(self._doc_lens.values()) / self._n_docs

    def idf(self, term: str) -> float:
        df = self._doc_freq.get(term, 0)
        return math.log((self._n_docs - df + 0.5) / (df + 0.5) + 1.0)

    def score(self, doc_id: str, query_terms: list[str]) -> float:
        if doc_id not in self._doc_lens or self._avgdl == 0.0:
            return 0.0
        dl = self._doc_lens[doc_id]
        total = 0.0
        for term in query_terms:
            f = self._term_freq.get(term, {}).get(doc_id, 0)
            if f == 0:
                continue
            tf_norm = (f * (self.k1 + 1.0)) / (
                f + self.k1 * (1.0 - self.b + self.b * dl / self._avgdl)
            )
            total += self.idf(term) * tf_norm
        return total

    def search(self, query: str, top_k: int = 10) -> list[tuple[str, float]]:
        terms = tokenise(query)
        if not terms:
            return []
        scores: dict[str, float] = {}
        candidate_ids: set[str] = set()
        for term in terms:
            candidate_ids.update(self._term_freq.get(term, {}).keys())
        for doc_id in candidate_ids:
            scores[doc_id] = self.score(doc_id, terms)
        ranked = sorted(scores.items(), key=lambda kv: (-kv[1], kv[0]))
        return [(d, s) for d, s in ranked[:top_k] if s > 0.0]


class CitationGraph:
    """Directed citation graph with forward and backward adjacency lists."""

    def __init__(self) -> None:
        self._forward: dict[str, list[str]] = {}
        self._backward: dict[str, list[str]] = {}

    def add_paper(self, paper: Paper) -> None:
        self._forward[paper.id] = list(paper.references)
        self._backward[paper.id] = list(paper.citations)

    def neighbours(self, doc_id: str) -> list[str]:
        out = list(self._forward.get(doc_id, []))
        out.extend(self._backward.get(doc_id, []))
        return out

    def expand(self, seeds: list[str], max_hops: int = 2) -> dict[str, int]:
        """Return a mapping of paper id to shortest hop distance from any seed."""
        distance: dict[str, int] = {sid: 0 for sid in seeds}
        queue: deque[str] = deque(seeds)
        while queue:
            current = queue.popleft()
            d = distance[current]
            if d >= max_hops:
                continue
            for neighbour in self.neighbours(current):
                if neighbour in distance:
                    continue
                distance[neighbour] = d + 1
                queue.append(neighbour)
        return distance


class ArxivMockClient:
    """Returns title, abstract, year, authors. No reference graph."""

    def __init__(self, corpus: list[Paper]) -> None:
        self._papers = {p.id: p for p in corpus}

    def search(self, query: str) -> list[Paper]:
        terms = set(tokenise(query))
        hits: list[Paper] = []
        for paper in self._papers.values():
            haystack = set(tokenise(paper.title + " " + paper.abstract))
            if terms & haystack:
                hits.append(Paper(
                    id=paper.id,
                    title=paper.title,
                    abstract=paper.abstract,
                    year=paper.year,
                    authors=list(paper.authors),
                    source="arxiv",
                ))
        return hits


class SemanticScholarMockClient:
    """Returns the same papers as arxiv plus references and citations."""

    def __init__(self, corpus: list[Paper]) -> None:
        self._papers = {p.id: p for p in corpus}

    def search(self, query: str) -> list[Paper]:
        terms = set(tokenise(query))
        hits: list[Paper] = []
        for paper in self._papers.values():
            haystack = set(tokenise(paper.title + " " + paper.abstract))
            if terms & haystack:
                hits.append(Paper(
                    id=paper.id,
                    title=paper.title,
                    abstract=paper.abstract,
                    year=paper.year,
                    authors=list(paper.authors),
                    references=list(paper.references),
                    citations=list(paper.citations),
                    source="s2",
                ))
        return hits

    def fetch(self, paper_id: str) -> Paper | None:
        paper = self._papers.get(paper_id)
        if paper is None:
            return None
        return Paper(
            id=paper.id,
            title=paper.title,
            abstract=paper.abstract,
            year=paper.year,
            authors=list(paper.authors),
            references=list(paper.references),
            citations=list(paper.citations),
            source="s2",
        )


@dataclass
class RetrievalConfig:
    top_k_lexical: int = 10
    max_hops: int = 2
    w_bm25: float = 0.5
    w_graph: float = 0.3
    w_recency: float = 0.2

    def __post_init__(self) -> None:
        if self.max_hops > 2:
            self.max_hops = 2


@dataclass
class RankedPaper:
    paper: Paper
    bm25_score: float
    graph_distance: int | None
    recency_score: float
    final_score: float

    def to_dict(self) -> dict:
        return {
            "id": self.paper.id,
            "title": self.paper.title,
            "year": self.paper.year,
            "bm25_score": round(self.bm25_score, 4),
            "graph_distance": self.graph_distance,
            "recency_score": round(self.recency_score, 4),
            "final_score": round(self.final_score, 4),
        }


@dataclass
class RetrievalResult:
    ranked: list[RankedPaper]
    hit_count: int
    average_score: float
    top_score: float
    wall_time_ms: float

    def to_dict(self) -> dict:
        return {
            "hit_count": self.hit_count,
            "average_score": round(self.average_score, 4),
            "top_score": round(self.top_score, 4),
            "wall_time_ms": round(self.wall_time_ms, 3),
            "ranked": [r.to_dict() for r in self.ranked],
        }


class RetrievalClient:
    """Wraps arxiv and semantic scholar mocks and merges lexical and graph hits."""

    def __init__(
        self,
        arxiv: ArxivMockClient,
        s2: SemanticScholarMockClient,
        corpus: list[Paper],
        config: RetrievalConfig | None = None,
    ) -> None:
        self._arxiv = arxiv
        self._s2 = s2
        self._cfg = config or RetrievalConfig()
        self._corpus = {p.id: p for p in corpus}
        self._index = BM25Index()
        for paper in corpus:
            self._index.add(paper.id, paper.title + " " + paper.abstract)
        self._index.finalise()
        self._graph = CitationGraph()
        for paper in corpus:
            self._graph.add_paper(paper)
        years = [p.year for p in corpus]
        self._year_min = min(years) if years else 0
        self._year_max = max(years) if years else 0

    def _recency(self, year: int) -> float:
        if self._year_max == self._year_min:
            return 1.0
        return (year - self._year_min) / (self._year_max - self._year_min)

    def _graph_score(self, distance: int | None) -> float:
        if distance is None:
            return 0.0
        if distance == 0:
            return 1.0
        if distance == 1:
            return 0.6
        if distance == 2:
            return 0.3
        return 0.0

    def _merge_paper(self, lexical: Paper | None, s2: Paper | None) -> Paper:
        base = self._corpus[(lexical or s2).id]
        return Paper(
            id=base.id,
            title=base.title,
            abstract=base.abstract,
            year=base.year,
            authors=list(base.authors),
            references=list(base.references),
            citations=list(base.citations),
            source="merged",
        )

    def search(self, query: str) -> RetrievalResult:
        start = time.perf_counter()
        terms = tokenise(query)
        if not terms:
            return RetrievalResult([], 0, 0.0, 0.0, (time.perf_counter() - start) * 1000.0)
        lexical_hits = self._index.search(query, self._cfg.top_k_lexical)
        seed_ids = [doc_id for doc_id, _ in lexical_hits]
        graph_distance = self._graph.expand(seed_ids, self._cfg.max_hops)
        merged_ids = set(seed_ids) | set(graph_distance.keys())
        max_bm25 = max((s for _, s in lexical_hits), default=0.0)
        ranked: list[RankedPaper] = []
        for doc_id in merged_ids:
            paper = self._corpus.get(doc_id)
            if paper is None:
                continue
            bm25 = self._index.score(doc_id, terms)
            distance = graph_distance.get(doc_id)
            graph_score = self._graph_score(distance)
            bm25_norm = bm25 / max_bm25 if max_bm25 > 0 else 0.0
            recency = self._recency(paper.year)
            final = (
                self._cfg.w_bm25 * bm25_norm
                + self._cfg.w_graph * graph_score
                + self._cfg.w_recency * recency
            )
            merged_paper = Paper(
                id=paper.id,
                title=paper.title,
                abstract=paper.abstract,
                year=paper.year,
                authors=list(paper.authors),
                references=list(paper.references),
                citations=list(paper.citations),
                source="merged",
            )
            ranked.append(RankedPaper(merged_paper, bm25, distance, recency, final))
        ranked.sort(key=lambda r: (-r.final_score, r.paper.id))
        scores = [r.final_score for r in ranked]
        avg = sum(scores) / len(scores) if scores else 0.0
        top = max(scores) if scores else 0.0
        wall_ms = (time.perf_counter() - start) * 1000.0
        return RetrievalResult(ranked, len(ranked), avg, top, wall_ms)


def build_corpus() -> list[Paper]:
    """Return a hundred paper mock corpus across five topics, with a citation graph.

    Topics: attention sparsity, retrieval augmentation, low rank adapters,
    dataset distillation, evaluation harnesses. Each topic gets twenty papers
    with intra topic references and a few cross topic edges.
    """
    topics = [
        ("attention sparsity", "attention sparsity head pruning routing block"),
        ("retrieval augmentation", "retrieval augmentation embedding index passage"),
        ("low rank adapters", "low rank adapter parameter fine tuning"),
        ("dataset distillation", "dataset distillation synthetic compact training"),
        ("evaluation harnesses", "evaluation harness benchmark task accuracy"),
    ]
    papers: list[Paper] = []
    for topic_idx, (label, terms) in enumerate(topics):
        for i in range(20):
            pid = f"p{topic_idx * 20 + i + 1:03d}"
            title = f"{label.title()} study {i + 1}"
            abstract = (
                f"This work investigates {label} and reports on {terms}. "
                f"We measure perplexity, accuracy, and wall time on small transformer baselines. "
                f"The study {i + 1} extends prior findings in topic {topic_idx + 1}."
            )
            year = 2018 + (i % 8)
            authors = [f"Author {topic_idx + 1}-{i + 1}", f"Coauthor {topic_idx + 1}-{i + 1}"]
            papers.append(Paper(pid, title, abstract, year, authors))
    by_id = {p.id: p for p in papers}
    for topic_idx in range(5):
        for i in range(20):
            pid = f"p{topic_idx * 20 + i + 1:03d}"
            paper = by_id[pid]
            if i >= 2:
                anchor_a = f"p{topic_idx * 20 + 1:03d}"
                anchor_b = f"p{topic_idx * 20 + 2:03d}"
                paper.references.extend([anchor_a, anchor_b])
                by_id[anchor_a].citations.append(pid)
                by_id[anchor_b].citations.append(pid)
            if i == 5:
                cross = f"p{((topic_idx + 1) % 5) * 20 + 1:03d}"
                paper.references.append(cross)
                by_id[cross].citations.append(pid)
    return papers


def build_client(config: RetrievalConfig | None = None) -> RetrievalClient:
    corpus = build_corpus()
    return RetrievalClient(ArxivMockClient(corpus), SemanticScholarMockClient(corpus), corpus, config)


def _demo() -> None:
    client = build_client(RetrievalConfig(top_k_lexical=5, max_hops=2))
    result = client.search("attention sparsity head pruning")
    print(json.dumps({
        "hit_count": result.hit_count,
        "top_score": round(result.top_score, 4),
        "top_three": [r.to_dict() for r in result.ranked[:3]],
    }, indent=2))


if __name__ == "__main__":
    _demo()

"""Result evaluator: improvement check, paired t test, log normalisation, verdict.

Conceptual references:
- ./docs/en.md (this lesson)
- Phase 19 Track A lessons 20-29 (agent harness primitives)

Stdlib + numpy (read of result lists). The t test math is pure stdlib.
Run: python3 code/main.py
"""

from __future__ import annotations

import json
import math
from dataclasses import dataclass, field
from typing import Iterable

import numpy as np


HIGHER = "higher_is_better"
LOWER = "lower_is_better"
LOG = "log"
LINEAR = "linear"


@dataclass
class ExperimentResultLike:
    """Subset of ExperimentResult fields the evaluator depends on.

    The runner in lesson 52 emits the same fields. The lesson 53 tests
    construct lightweight instances directly so the evaluator can be tested
    in isolation.
    """
    spec_id: str
    terminal: str
    metrics: dict


@dataclass
class MetricSpec:
    name: str
    direction: str = HIGHER
    scale: str = LINEAR

    def validate(self) -> None:
        if self.direction not in (HIGHER, LOWER):
            raise ValueError(f"unknown direction {self.direction!r}")
        if self.scale not in (LINEAR, LOG):
            raise ValueError(f"unknown scale {self.scale!r}")


@dataclass
class Verdict:
    hypothesis_id: int
    metric: str
    direction: str
    scale: str
    candidate_mean: float
    baseline_mean: float
    improvement: float
    p_value: float | None
    significance_threshold: float
    improvement_threshold: float
    verdict: str
    rationale: str

    def to_dict(self) -> dict:
        return {
            "hypothesis_id": self.hypothesis_id,
            "metric": self.metric,
            "direction": self.direction,
            "scale": self.scale,
            "candidate_mean": round(self.candidate_mean, 6),
            "baseline_mean": round(self.baseline_mean, 6),
            "improvement": round(self.improvement, 6),
            "p_value": None if self.p_value is None else round(self.p_value, 6),
            "significance_threshold": self.significance_threshold,
            "improvement_threshold": self.improvement_threshold,
            "verdict": self.verdict,
            "rationale": self.rationale,
        }


class PairingError(ValueError):
    """Raised when candidate and baseline results cannot be paired by seed."""


def _lentz_betacf(a: float, b: float, x: float, max_iter: int = 200, eps: float = 1e-12) -> float:
    """Continued fraction for the regularised incomplete beta function via Lentz."""
    qab = a + b
    qap = a + 1.0
    qam = a - 1.0
    c = 1.0
    d = 1.0 - qab * x / qap
    if abs(d) < eps:
        d = eps
    d = 1.0 / d
    h = d
    for m in range(1, max_iter + 1):
        m2 = 2 * m
        aa = m * (b - m) * x / ((qam + m2) * (a + m2))
        d = 1.0 + aa * d
        if abs(d) < eps:
            d = eps
        c = 1.0 + aa / c
        if abs(c) < eps:
            c = eps
        d = 1.0 / d
        h *= d * c
        aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2))
        d = 1.0 + aa * d
        if abs(d) < eps:
            d = eps
        c = 1.0 + aa / c
        if abs(c) < eps:
            c = eps
        d = 1.0 / d
        delta = d * c
        h *= delta
        if abs(delta - 1.0) < eps:
            return h
    return h


def regularised_incomplete_beta(a: float, b: float, x: float) -> float:
    """I_x(a, b) via the standard Lentz continued fraction, symmetric in x."""
    if x < 0.0 or x > 1.0:
        raise ValueError("x out of [0, 1]")
    if x == 0.0:
        return 0.0
    if x == 1.0:
        return 1.0
    log_bt = (
        math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b)
        + a * math.log(x) + b * math.log(1.0 - x)
    )
    bt = math.exp(log_bt)
    if x < (a + 1.0) / (a + b + 2.0):
        return bt * _lentz_betacf(a, b, x) / a
    return 1.0 - bt * _lentz_betacf(b, a, 1.0 - x) / b


def two_sided_t_p_value(t_stat: float, df: int) -> float:
    """Two sided p value for a t statistic with df degrees of freedom."""
    if df <= 0:
        return 1.0
    x = df / (df + t_stat * t_stat)
    p = regularised_incomplete_beta(df / 2.0, 0.5, x)
    return max(0.0, min(1.0, p))


def paired_t_test(candidate: list[float], baseline: list[float]) -> tuple[float, float | None, int]:
    """Return (mean_diff, p_value, n). p_value is None when n < 2."""
    if len(candidate) != len(baseline):
        raise PairingError("candidate and baseline lengths disagree")
    n = len(candidate)
    if n < 2:
        if n == 0:
            return 0.0, None, 0
        return float(candidate[0] - baseline[0]), None, n
    diffs = np.array(candidate) - np.array(baseline)
    mean_diff = float(diffs.mean())
    var_diff = float(diffs.var(ddof=1))
    if var_diff == 0.0:
        return mean_diff, (0.0 if mean_diff != 0.0 else 1.0), n
    t_stat = mean_diff / math.sqrt(var_diff / n)
    p = two_sided_t_p_value(t_stat, n - 1)
    return mean_diff, p, n


def _pair_by_seed(
    candidates: list[ExperimentResultLike],
    baselines: list[ExperimentResultLike],
    metric: str,
) -> tuple[list[float], list[float]]:
    cand_map: dict[int, float] = {}
    for r in candidates:
        seed = r.metrics.get("seed")
        if seed is None:
            raise PairingError(f"candidate {r.spec_id} missing seed")
        seed_i = int(seed)
        if seed_i in cand_map:
            raise PairingError(f"duplicate candidate seed {seed_i} (spec {r.spec_id})")
        cand_map[seed_i] = float(r.metrics[metric])
    base_map: dict[int, float] = {}
    for r in baselines:
        seed = r.metrics.get("seed")
        if seed is None:
            raise PairingError(f"baseline {r.spec_id} missing seed")
        seed_i = int(seed)
        if seed_i in base_map:
            raise PairingError(f"duplicate baseline seed {seed_i} (spec {r.spec_id})")
        base_map[seed_i] = float(r.metrics[metric])
    shared = sorted(set(cand_map.keys()) & set(base_map.keys()))
    if not shared:
        raise PairingError("no shared seeds between candidate and baseline")
    return [cand_map[s] for s in shared], [base_map[s] for s in shared]


def _improvement(candidate_mean: float, baseline_mean: float, direction: str) -> float:
    denom = abs(baseline_mean) if baseline_mean != 0.0 else 1.0
    raw = (candidate_mean - baseline_mean) / denom
    if direction == LOWER:
        return -raw
    return raw


def _log_transform(values: list[float], scale: str) -> list[float]:
    if scale != LOG:
        return list(values)
    out = []
    for v in values:
        if v <= 0.0:
            raise ValueError(f"log scale metric must be positive, got {v}")
        out.append(math.log(v))
    return out


@dataclass
class EvaluatorConfig:
    improvement_threshold: float = 0.02
    significance_threshold: float = 0.05


class Evaluator:
    """Pure function over (candidate, baseline) result lists; returns a Verdict."""

    def __init__(self, config: EvaluatorConfig | None = None) -> None:
        self._cfg = config or EvaluatorConfig()

    def evaluate(
        self,
        hypothesis_id: int,
        metric_spec: MetricSpec,
        candidates: list[ExperimentResultLike],
        baselines: list[ExperimentResultLike],
    ) -> Verdict:
        metric_spec.validate()
        bad = [r for r in [*candidates, *baselines] if r.terminal != "ok"]
        if bad:
            return self._failed_verdict(hypothesis_id, metric_spec, bad)
        cand_vals, base_vals = _pair_by_seed(candidates, baselines, metric_spec.name)
        cand_t = _log_transform(cand_vals, metric_spec.scale)
        base_t = _log_transform(base_vals, metric_spec.scale)
        mean_diff, p_value, n = paired_t_test(cand_t, base_t)
        cand_mean = float(np.mean(cand_vals))
        base_mean = float(np.mean(base_vals))
        cand_mean_t = float(np.mean(cand_t))
        base_mean_t = float(np.mean(base_t))
        improvement = _improvement(cand_mean_t, base_mean_t, metric_spec.direction)
        verdict, rationale = self._verdict(improvement, p_value, n)
        return Verdict(
            hypothesis_id=hypothesis_id,
            metric=metric_spec.name,
            direction=metric_spec.direction,
            scale=metric_spec.scale,
            candidate_mean=cand_mean,
            baseline_mean=base_mean,
            improvement=improvement,
            p_value=p_value,
            significance_threshold=self._cfg.significance_threshold,
            improvement_threshold=self._cfg.improvement_threshold,
            verdict=verdict,
            rationale=rationale,
        )

    def _failed_verdict(
        self, hypothesis_id: int, metric_spec: MetricSpec, bad: list[ExperimentResultLike]
    ) -> Verdict:
        terminals = sorted({r.terminal for r in bad})
        rationale = f"runs failed with terminals {terminals}"
        return Verdict(
            hypothesis_id=hypothesis_id,
            metric=metric_spec.name,
            direction=metric_spec.direction,
            scale=metric_spec.scale,
            candidate_mean=0.0,
            baseline_mean=0.0,
            improvement=0.0,
            p_value=None,
            significance_threshold=self._cfg.significance_threshold,
            improvement_threshold=self._cfg.improvement_threshold,
            verdict="failed",
            rationale=rationale,
        )

    def _verdict(self, improvement: float, p_value: float | None, n: int) -> tuple[str, str]:
        if abs(improvement) < self._cfg.improvement_threshold:
            return "noise", (
                f"improvement {improvement:.4f} is below threshold "
                f"{self._cfg.improvement_threshold}"
            )
        if p_value is None:
            return "noise", f"only {n} paired sample(s); cannot run significance test"
        if p_value > self._cfg.significance_threshold:
            return "noise", (
                f"p value {p_value:.4f} exceeds significance threshold "
                f"{self._cfg.significance_threshold}"
            )
        if improvement > 0:
            return "improved", (
                f"improvement {improvement:.4f} significant at p={p_value:.4f}"
            )
        return "regressed", (
            f"regression {improvement:.4f} significant at p={p_value:.4f}"
        )


def _demo() -> None:
    def result(seed: int, perplexity: float) -> ExperimentResultLike:
        return ExperimentResultLike(
            spec_id=f"demo_{seed}",
            terminal="ok",
            metrics={"seed": seed, "perplexity": perplexity, "final_loss": math.log(perplexity)},
        )

    candidates = [result(s, 28.0 - 0.5 * s + (s % 3) * 0.2) for s in range(8)]
    baselines = [result(s, 32.0 - 0.4 * s + (s % 3) * 0.2) for s in range(8)]
    metric_spec = MetricSpec(name="perplexity", direction=LOWER, scale=LOG)
    evaluator = Evaluator()
    verdict = evaluator.evaluate(1, metric_spec, candidates, baselines)
    print(json.dumps(verdict.to_dict(), indent=2))


if __name__ == "__main__":
    _demo()

"""LaTeX paper skeleton generator with figure injection and a mocked prose generator.

Conceptual references:
- ./docs/en.md (this lesson)
- Phase 19 lessons 50-53 (earlier auto-research stages)

Stdlib only. Run: python3 code/main.py
"""

from __future__ import annotations

import json
import os
import re
from dataclasses import dataclass, field
from typing import Callable, Iterable


class PaperValidationError(Exception):
    """Raised when the paper fails a structural gate before render."""


@dataclass
class BibEntry:
    key: str
    entry_type: str
    fields: dict

    def to_bibtex(self) -> str:
        lines = [f"@{self.entry_type}{{{self.key},"]
        for k, v in sorted(self.fields.items()):
            safe = str(v).replace("{", "").replace("}", "")
            lines.append(f"  {k} = {{{safe}}},")
        lines.append("}")
        return "\n".join(lines)


@dataclass
class Figure:
    id: str
    path: str
    caption: str
    width: str = "0.8\\textwidth"

    @property
    def label(self) -> str:
        return f"fig:{self.id}"


@dataclass
class Section:
    id: str
    title: str
    body: str = ""
    cites: list[str] = field(default_factory=list)
    figure_refs: list[str] = field(default_factory=list)

    @property
    def label(self) -> str:
        return f"sec:{self.id}"


@dataclass
class Paper:
    title: str
    authors: list[str]
    abstract: str
    sections: list[Section] = field(default_factory=list)
    figures: list[Figure] = field(default_factory=list)
    bibliography: list[BibEntry] = field(default_factory=list)


ProseGenerator = Callable[[Section, Paper], str]


def _validate(paper: Paper) -> None:
    if not paper.title.strip():
        raise PaperValidationError("title is empty")
    if not paper.abstract.strip():
        raise PaperValidationError("abstract is empty")

    fig_ids: set[str] = set()
    for fig in paper.figures:
        if fig.id in fig_ids:
            raise PaperValidationError(f"duplicate figure id: {fig.id}")
        fig_ids.add(fig.id)

    bib_keys: set[str] = set()
    for b in paper.bibliography:
        if b.key in bib_keys:
            raise PaperValidationError(f"duplicate bibliography key: {b.key}")
        bib_keys.add(b.key)
    for sec in paper.sections:
        for key in sec.cites:
            if key not in bib_keys:
                raise PaperValidationError(
                    f"section {sec.id!r} cites unknown bibliography key {key!r}"
                )
        for fid in sec.figure_refs:
            if fid not in fig_ids:
                raise PaperValidationError(
                    f"section {sec.id!r} references unknown figure id {fid!r}"
                )


def _escape_latex(text: str) -> str:
    repl = {
        "\\": r"\textbackslash{}",
        "&": r"\&",
        "%": r"\%",
        "$": r"\$",
        "#": r"\#",
        "_": r"\_",
        "{": r"\{",
        "}": r"\}",
        "~": r"\textasciitilde{}",
        "^": r"\textasciicircum{}",
    }
    out_chars: list[str] = []
    for ch in text:
        out_chars.append(repl.get(ch, ch))
    return "".join(out_chars)


def render_latex(paper: Paper) -> str:
    """Render a Paper to a full LaTeX document string."""
    _validate(paper)

    lines: list[str] = []
    lines.append("\\documentclass{article}")
    lines.append("\\usepackage{graphicx}")
    lines.append("\\usepackage{hyperref}")
    lines.append("\\title{" + _escape_latex(paper.title) + "}")
    lines.append("\\author{" + " \\and ".join(_escape_latex(a) for a in paper.authors) + "}")
    lines.append("\\begin{document}")
    lines.append("\\maketitle")
    lines.append("\\begin{abstract}")
    lines.append(_escape_latex(paper.abstract))
    lines.append("\\end{abstract}")

    for sec in paper.sections:
        lines.append("\\section{" + _escape_latex(sec.title) + "}")
        lines.append("\\label{" + sec.label + "}")
        lines.append(sec.body if sec.body else "% body pending")
        for fid in sec.figure_refs:
            lines.append("See Figure~\\ref{fig:" + fid + "}.")
        for cite in sec.cites:
            lines.append("See~\\cite{" + cite + "}.")

    for fig in paper.figures:
        lines.append("\\begin{figure}")
        lines.append("\\centering")
        lines.append("\\includegraphics[width=" + fig.width + "]{" + fig.path + "}")
        lines.append("\\caption{" + _escape_latex(fig.caption) + "}")
        lines.append("\\label{" + fig.label + "}")
        lines.append("\\end{figure}")

    if paper.bibliography:
        lines.append("\\bibliographystyle{plain}")
        lines.append("\\bibliography{references}")

    lines.append("\\end{document}")
    return "\n".join(lines) + "\n"


def render_bibtex(paper: Paper) -> str:
    return "\n\n".join(b.to_bibtex() for b in paper.bibliography) + ("\n" if paper.bibliography else "")


class MockProseGenerator:
    """Deterministic prose generator. Substitutes for a model in tests and demos."""

    def __init__(self, outlines: dict[str, str]) -> None:
        self.outlines = outlines

    def __call__(self, section: Section, paper: Paper) -> str:
        seed = self.outlines.get(section.id, section.title)
        first = f"In this section we discuss {section.title.lower()}: {seed}."
        bits: list[str] = []
        for fid in section.figure_refs:
            bits.append(f"Figure~\\ref{{fig:{fid}}} shows the relevant artifact.")
        for c in section.cites:
            bits.append(f"This builds on prior work~\\cite{{{c}}}.")
        second = " ".join(bits) if bits else "We discuss implications below."
        return first + "\n\n" + second


def read_experiment_manifest(manifests: Iterable[dict], paper_dir: str) -> list[Figure]:
    """Convert experiment output manifests into Figure records.

    Each manifest is expected to be a dict of shape:
        {"name": str, "artifacts": [{"path": str, "caption": str}, ...]}
    Paths in artifacts may be absolute or relative to the manifest's cwd; we
    normalise them relative to paper_dir.
    """
    figs: list[Figure] = []
    counter = 0
    for m in manifests:
        name = m.get("name", "exp")
        artifacts = m.get("artifacts", [])
        for art in artifacts:
            path = art.get("path", "")
            caption = art.get("caption", "")
            if not path:
                continue
            counter += 1
            try:
                rel = os.path.relpath(path, paper_dir)
            except ValueError:
                rel = path
            fid = re.sub(r"[^a-zA-Z0-9]+", "-", f"{name}-{counter}").strip("-").lower()
            figs.append(Figure(id=fid, path=rel, caption=caption or name))
    return figs


@dataclass
class PaperWriter:
    prose: ProseGenerator

    def fill_prose(self, paper: Paper) -> Paper:
        for sec in paper.sections:
            if not sec.body:
                sec.body = self.prose(sec, paper)
        return paper

    def write(self, paper: Paper, out_dir: str) -> dict:
        """Validate, fill prose, render, and write three files. Returns the manifest dict."""
        os.makedirs(out_dir, exist_ok=True)
        self.fill_prose(paper)
        tex = render_latex(paper)
        bib = render_bibtex(paper)

        tex_path = os.path.join(out_dir, "paper.tex")
        bib_path = os.path.join(out_dir, "references.bib")
        man_path = os.path.join(out_dir, "manifest.json")

        with open(tex_path, "w", encoding="utf-8") as f:
            f.write(tex)
        with open(bib_path, "w", encoding="utf-8") as f:
            f.write(bib)

        manifest = {
            "title": paper.title,
            "authors": list(paper.authors),
            "sections": [
                {"id": s.id, "title": s.title, "cites": list(s.cites),
                 "figure_refs": list(s.figure_refs), "body_chars": len(s.body)}
                for s in paper.sections
            ],
            "figures": [
                {"id": f.id, "path": f.path, "caption": f.caption, "label": f.label}
                for f in paper.figures
            ],
            "bibliography": [b.key for b in paper.bibliography],
            "tex_path": tex_path,
            "bib_path": bib_path,
        }
        with open(man_path, "w", encoding="utf-8") as f:
            json.dump(manifest, f, indent=2, sort_keys=True)
        return manifest


def demo(out_dir: str | None = None) -> dict:
    """Self-contained demo. Builds a small paper from two mocked experiments.

    Writes into a temp directory by default so the worktree stays clean.
    """
    import tempfile as _tempfile
    if out_dir is None:
        out_dir = _tempfile.mkdtemp(prefix="paper-writer-demo-")
    experiments = [
        {"name": "loss-curve", "artifacts": [
            {"path": "figs/loss.pdf", "caption": "Training loss across epochs"},
        ]},
        {"name": "ablation", "artifacts": [
            {"path": "figs/ablation.pdf", "caption": "Ablation over decoder width"},
        ]},
    ]
    figs = read_experiment_manifest(experiments, out_dir)
    paper = Paper(
        title="Auto-Research Loop: Empirical Notes",
        authors=["Lab Bot"],
        abstract="We describe a small experiment harness that emits LaTeX from structured outputs.",
        sections=[
            Section(id="intro", title="Introduction", cites=["smith2020"],
                    figure_refs=[]),
            Section(id="method", title="Method", cites=["jones2021"],
                    figure_refs=[figs[0].id]),
            Section(id="results", title="Results", cites=[],
                    figure_refs=[figs[1].id]),
        ],
        figures=figs,
        bibliography=[
            BibEntry(key="smith2020", entry_type="article",
                     fields={"title": "On harnesses", "author": "Smith", "year": "2020"}),
            BibEntry(key="jones2021", entry_type="article",
                     fields={"title": "On loops", "author": "Jones", "year": "2021"}),
        ],
    )
    prose = MockProseGenerator(outlines={
        "intro": "we motivate the auto-research loop",
        "method": "we describe the skeleton-first writer",
        "results": "we present two ablations",
    })
    writer = PaperWriter(prose=prose)
    return writer.write(paper, out_dir)


if __name__ == "__main__":
    manifest = demo()
    print(json.dumps({
        "sections": len(manifest["sections"]),
        "figures": len(manifest["figures"]),
        "bib_keys": manifest["bibliography"],
        "tex_path": manifest["tex_path"],
    }, indent=2))

"""Multi-turn critic loop for a paper draft with five fixed scoring dimensions.

Conceptual references:
- ./docs/en.md (this lesson)
- Phase 19 lesson 54 (paper writer; provides the draft shape)
- Phase 19 lessons 50-53 (earlier auto-research stages)

Stdlib only. Run: python3 code/main.py
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from typing import Callable, Protocol


DIMENSIONS: tuple[str, ...] = (
    "clarity",
    "novelty",
    "evidence",
    "methodology",
    "related_work",
)


@dataclass
class MiniSection:
    """Minimal section shape for the critic loop. Mirrors lesson 54 Section."""
    id: str
    title: str
    body: str = ""
    figure_refs: list[str] = field(default_factory=list)
    cites: list[str] = field(default_factory=list)


@dataclass
class MiniPaper:
    """Minimal paper shape for the critic loop. Mirrors lesson 54 Paper."""
    title: str
    abstract: str
    sections: list[MiniSection] = field(default_factory=list)
    originality_tag: str = "low"
    citation_count_target: int = 4
    figure_count_target: int = 2


@dataclass
class Suggestion:
    dimension: str
    target_section_id: str | None
    edit: str

    def to_dict(self) -> dict:
        return {
            "dimension": self.dimension,
            "target_section_id": self.target_section_id,
            "edit": self.edit,
        }


@dataclass
class Critique:
    round: int
    scores: dict[str, float]
    suggestions: list[Suggestion]
    reason: str

    def mean(self) -> float:
        if not self.scores:
            return 0.0
        return sum(self.scores.values()) / len(self.scores)

    def to_dict(self) -> dict:
        return {
            "round": self.round,
            "scores": dict(self.scores),
            "mean": self.mean(),
            "suggestions": [s.to_dict() for s in self.suggestions],
            "reason": self.reason,
        }


class Critic(Protocol):
    def __call__(self, paper: MiniPaper, round_: int) -> Critique: ...


class Reviser(Protocol):
    def __call__(self, paper: MiniPaper, suggestions: list[Suggestion]) -> MiniPaper: ...


@dataclass
class LoopTrace:
    round: int
    scores: dict[str, float]
    mean: float
    suggestions_applied: int
    verdict: str

    def to_dict(self) -> dict:
        return {
            "round": self.round,
            "scores": dict(self.scores),
            "mean": self.mean,
            "suggestions_applied": self.suggestions_applied,
            "verdict": self.verdict,
        }


@dataclass
class LoopResult:
    status: str
    reason: str
    rounds_used: int
    final_scores: dict[str, float]
    final_mean: float
    paper: MiniPaper
    trace: list[LoopTrace]

    def to_dict(self) -> dict:
        return {
            "status": self.status,
            "reason": self.reason,
            "rounds_used": self.rounds_used,
            "final_scores": dict(self.final_scores),
            "final_mean": self.final_mean,
            "trace": [t.to_dict() for t in self.trace],
        }


class CriticLoop:
    """Drives critic -> reviser -> convergence-check until a stop condition fires."""

    def __init__(
        self,
        critic: Critic,
        reviser: Reviser,
        max_rounds: int = 5,
        target_score: float = 8.0,
        plateau_epsilon: float = 0.1,
        plateau_window: int = 2,
    ) -> None:
        if max_rounds < 1:
            raise ValueError("max_rounds must be >= 1")
        if plateau_window < 1:
            raise ValueError("plateau_window must be >= 1")
        self.critic = critic
        self.reviser = reviser
        self.max_rounds = max_rounds
        self.target_score = target_score
        self.plateau_epsilon = plateau_epsilon
        self.plateau_window = plateau_window

    def _target_met(self, critique: Critique) -> bool:
        return all(critique.scores.get(d, 0.0) >= self.target_score for d in DIMENSIONS)

    def _plateau(self, trace: list[LoopTrace]) -> bool:
        if len(trace) < self.plateau_window + 1:
            return False
        recent = trace[-(self.plateau_window + 1):]
        for i in range(1, len(recent)):
            if recent[i].mean - recent[i - 1].mean > self.plateau_epsilon:
                return False
        return True

    def run(self, paper: MiniPaper) -> LoopResult:
        trace: list[LoopTrace] = []
        critique: Critique | None = None

        for round_ in range(1, self.max_rounds + 1):
            critique = self.critic(paper, round_)
            applied = len(critique.suggestions)

            if self._target_met(critique):
                trace.append(LoopTrace(
                    round=round_, scores=dict(critique.scores),
                    mean=critique.mean(), suggestions_applied=0,
                    verdict="target",
                ))
                return LoopResult(
                    status="converged", reason="target",
                    rounds_used=round_, final_scores=dict(critique.scores),
                    final_mean=critique.mean(), paper=paper, trace=trace,
                )

            interim = LoopTrace(
                round=round_, scores=dict(critique.scores),
                mean=critique.mean(), suggestions_applied=applied,
                verdict="continue",
            )
            trace.append(interim)

            if self._plateau(trace):
                interim.verdict = "plateau"
                return LoopResult(
                    status="converged", reason="plateau",
                    rounds_used=round_, final_scores=dict(critique.scores),
                    final_mean=critique.mean(), paper=paper, trace=trace,
                )

            paper = self.reviser(paper, critique.suggestions)

        final_scores = dict(critique.scores) if critique is not None else {d: 0.0 for d in DIMENSIONS}
        final_mean = critique.mean() if critique is not None else 0.0
        if trace:
            trace[-1].verdict = "budget"
        return LoopResult(
            status="stopped", reason="budget",
            rounds_used=self.max_rounds, final_scores=final_scores,
            final_mean=final_mean, paper=paper, trace=trace,
        )


def deterministic_score(paper: MiniPaper) -> dict[str, float]:
    """Score a paper deterministically across the five dimensions, 0..10 each."""
    body_lens = [len(s.body) for s in paper.sections]
    avg_body = (sum(body_lens) / len(body_lens)) if body_lens else 0.0
    section_titles = {s.title.lower() for s in paper.sections}

    clarity = min(10.0, 3.0 + avg_body / 50.0)

    if paper.originality_tag == "high":
        novelty = 9.0
    elif paper.originality_tag == "medium":
        novelty = 6.0
    else:
        novelty = 3.0

    fig_refs = sum(1 for s in paper.sections for _ in s.figure_refs)
    cites = sum(len(s.cites) for s in paper.sections)
    evidence = min(10.0, 2.0 + 2.0 * fig_refs + 1.5 * cites)

    has_method = any(
        s.title.lower().startswith("method") and s.body for s in paper.sections
    )
    methodology = 9.0 if has_method else 4.0

    has_related = (
        "related work" in section_titles
        and any(
            s.title.lower() == "related work" and s.body
            for s in paper.sections
        )
    )
    related_work = 9.0 if has_related else 4.0

    return {
        "clarity": round(clarity, 2),
        "novelty": round(novelty, 2),
        "evidence": round(evidence, 2),
        "methodology": round(methodology, 2),
        "related_work": round(related_work, 2),
    }


def deterministic_critic(paper: MiniPaper, round_: int) -> Critique:
    """Score the paper and emit one suggestion per dimension that is below target."""
    scores = deterministic_score(paper)
    suggestions: list[Suggestion] = []

    def first_section_id(default: str = "intro") -> str:
        return paper.sections[0].id if paper.sections else default

    if scores["clarity"] < 8.0:
        target = paper.sections[-1].id if paper.sections else None
        suggestions.append(Suggestion(
            dimension="clarity",
            target_section_id=target,
            edit="expand-body",
        ))
    if scores["novelty"] < 8.0:
        suggestions.append(Suggestion(
            dimension="novelty",
            target_section_id=None,
            edit="bump-originality",
        ))
    if scores["evidence"] < 8.0:
        suggestions.append(Suggestion(
            dimension="evidence",
            target_section_id=first_section_id(),
            edit="add-figure-and-cite",
        ))
    if scores["methodology"] < 8.0:
        suggestions.append(Suggestion(
            dimension="methodology",
            target_section_id=None,
            edit="add-method-section",
        ))
    if scores["related_work"] < 8.0:
        suggestions.append(Suggestion(
            dimension="related_work",
            target_section_id=None,
            edit="add-related-work-section",
        ))

    reason = "fully-met" if not suggestions else f"{len(suggestions)} below target"
    return Critique(round=round_, scores=scores, suggestions=suggestions, reason=reason)


def deterministic_reviser(paper: MiniPaper, suggestions: list[Suggestion]) -> MiniPaper:
    """Apply each suggestion's edit deterministically. Returns a mutated paper (same object)."""
    fig_counter = 0
    cite_counter = 0
    for s in paper.sections:
        fig_counter += len(s.figure_refs)
        cite_counter += len(s.cites)

    for sug in suggestions:
        if sug.edit == "expand-body":
            for sec in paper.sections:
                if sec.id == sug.target_section_id:
                    sec.body = (sec.body + " " + ("x" * 80)).strip()
                    break
        elif sug.edit == "bump-originality":
            if paper.originality_tag == "low":
                paper.originality_tag = "medium"
            elif paper.originality_tag == "medium":
                paper.originality_tag = "high"
        elif sug.edit == "add-figure-and-cite":
            target_id = sug.target_section_id or (paper.sections[0].id if paper.sections else None)
            for sec in paper.sections:
                if sec.id == target_id:
                    fig_counter += 1
                    cite_counter += 1
                    sec.figure_refs.append(f"f{fig_counter}")
                    sec.cites.append(f"c{cite_counter}")
                    break
        elif sug.edit == "add-method-section":
            if not any(s.title.lower().startswith("method") for s in paper.sections):
                paper.sections.append(MiniSection(
                    id="method", title="Method",
                    body="A description of the method follows. " + ("x" * 200),
                ))
            else:
                for sec in paper.sections:
                    if sec.title.lower().startswith("method") and not sec.body:
                        sec.body = "A description of the method follows. " + ("x" * 200)
                        break
        elif sug.edit == "add-related-work-section":
            if not any(s.title.lower() == "related work" for s in paper.sections):
                paper.sections.append(MiniSection(
                    id="related-work", title="Related Work",
                    body="We survey adjacent work. " + ("x" * 200),
                ))
            else:
                for sec in paper.sections:
                    if sec.title.lower() == "related work" and not sec.body:
                        sec.body = "We survey adjacent work. " + ("x" * 200)
                        break
    return paper


def make_deterministic_critic_pair() -> tuple[Critic, Reviser]:
    return deterministic_critic, deterministic_reviser


def demo() -> dict:
    paper = MiniPaper(
        title="Auto-Research Loop",
        abstract="abstract",
        sections=[
            MiniSection(id="intro", title="Introduction", body="short intro"),
        ],
        originality_tag="low",
    )
    critic, reviser = make_deterministic_critic_pair()
    loop = CriticLoop(critic=critic, reviser=reviser, max_rounds=6, target_score=8.0)
    result = loop.run(paper)
    return result.to_dict()


if __name__ == "__main__":
    print(json.dumps(demo(), indent=2))

"""Task spec format: JSONL schema, validator, post-process, fixture loader.

Conceptual references:
- ./docs/en.md (this lesson)
- Phase 19 Track B foundations

Stdlib only. Run: python3 code/main.py
"""

from __future__ import annotations

import json
import os
import re
import sys
from dataclasses import dataclass, field
from typing import Any, Iterable

REQUIRED_FIELDS = ("task_id", "category", "prompt", "targets", "metric_name", "post_process")
OPTIONAL_FIELDS = ("few_shot_examples", "metadata")
ALLOWED_FIELDS = set(REQUIRED_FIELDS) | set(OPTIONAL_FIELDS)

CATEGORIES = ("arithmetic", "mcq", "code_exec", "classification", "summary")
METRICS = ("exact_match", "f1", "bleu_4", "rouge_l", "accuracy", "code_exec")
POST_PROCESS = (
    "none",
    "strip_whitespace",
    "lower",
    "extract_letter",
    "extract_code_block",
    "extract_first_line",
)

LEGAL_CATEGORY_METRIC = {
    "arithmetic": {"exact_match", "f1"},
    "mcq": {"exact_match", "accuracy"},
    "code_exec": {"code_exec"},
    "classification": {"exact_match", "accuracy", "f1"},
    "summary": {"exact_match", "f1", "bleu_4", "rouge_l"},
}

FEW_SHOT_MAX = 8
TASK_ID_RE = re.compile(r"^[A-Za-z0-9_\-]+$")
MCQ_TARGET_RE = re.compile(r"^[A-E]$")


@dataclass
class ValidationError:
    line_number: int
    task_id: str
    rule: str
    field_name: str
    detail: str

    def to_dict(self) -> dict:
        return {
            "line_number": self.line_number,
            "task_id": self.task_id,
            "rule": self.rule,
            "field": self.field_name,
            "detail": self.detail,
        }


@dataclass
class TaskSpec:
    task_id: str
    category: str
    prompt: str
    targets: list[str]
    metric_name: str
    post_process: str
    few_shot_examples: list[dict] = field(default_factory=list)
    metadata: dict = field(default_factory=dict)

    def to_dict(self) -> dict:
        return {
            "task_id": self.task_id,
            "category": self.category,
            "prompt": self.prompt,
            "targets": list(self.targets),
            "metric_name": self.metric_name,
            "post_process": self.post_process,
            "few_shot_examples": list(self.few_shot_examples),
            "metadata": dict(self.metadata),
        }


def _check_required(record: dict) -> tuple[str, str] | None:
    for f in REQUIRED_FIELDS:
        if f not in record:
            return ("missing_required", f)
    return None


def _check_unknown_fields(record: dict) -> tuple[str, str] | None:
    for k in record.keys():
        if k not in ALLOWED_FIELDS:
            return ("unknown_field", k)
    return None


def _check_types(record: dict) -> tuple[str, str, str] | None:
    if not isinstance(record["task_id"], str):
        return ("bad_type", "task_id", "must be string")
    if not TASK_ID_RE.match(record["task_id"]):
        return ("bad_value", "task_id", "must match [A-Za-z0-9_-]+")
    if record["category"] not in CATEGORIES:
        return ("bad_value", "category", f"must be one of {sorted(CATEGORIES)}")
    if not isinstance(record["prompt"], str) or not record["prompt"]:
        return ("bad_type", "prompt", "must be non-empty string")
    if record["prompt"] != record["prompt"].rstrip():
        return ("bad_value", "prompt", "trailing whitespace not allowed")
    if not isinstance(record["targets"], list) or not record["targets"]:
        return ("bad_type", "targets", "must be non-empty list")
    for t in record["targets"]:
        if not isinstance(t, str):
            return ("bad_type", "targets", "all elements must be strings")
    if record["metric_name"] not in METRICS:
        return ("bad_value", "metric_name", f"must be one of {sorted(METRICS)}")
    if record["post_process"] not in POST_PROCESS:
        return ("bad_value", "post_process", f"must be one of {sorted(POST_PROCESS)}")
    if "few_shot_examples" in record:
        if not isinstance(record["few_shot_examples"], list):
            return ("bad_type", "few_shot_examples", "must be list")
        if len(record["few_shot_examples"]) > FEW_SHOT_MAX:
            return ("bad_value", "few_shot_examples", f"max {FEW_SHOT_MAX} entries")
        for ex in record["few_shot_examples"]:
            if not isinstance(ex, dict):
                return ("bad_type", "few_shot_examples", "entries must be objects")
            if "prompt" not in ex or "completion" not in ex:
                return ("bad_type", "few_shot_examples", "needs prompt and completion")
            if not isinstance(ex["prompt"], str) or not isinstance(ex["completion"], str):
                return ("bad_type", "few_shot_examples", "prompt/completion must be strings")
    if "metadata" in record and not isinstance(record["metadata"], dict):
        return ("bad_type", "metadata", "must be object")
    return None


def _check_category_metric(record: dict) -> tuple[str, str, str] | None:
    cat = record["category"]
    metric = record["metric_name"]
    if metric not in LEGAL_CATEGORY_METRIC[cat]:
        return (
            "illegal_pair",
            "metric_name",
            f"{metric} not allowed for category {cat}",
        )
    if cat == "mcq":
        if len(record["targets"]) != 1:
            return ("bad_value", "targets", "mcq needs exactly one target")
        if not MCQ_TARGET_RE.match(record["targets"][0]):
            return ("bad_value", "targets", "mcq target must be a letter A-E")
    return None


def _embedded_few_shot(prompt: str) -> bool:
    lowered = prompt.lower()
    markers = ("question:", "q:", "example:")
    hits = sum(lowered.count(m) for m in markers)
    return hits > 1


def validate_task(record: dict, line_number: int = 0) -> list[ValidationError]:
    errors: list[ValidationError] = []
    tid = record.get("task_id", "?") if isinstance(record, dict) else "?"
    if not isinstance(record, dict):
        errors.append(ValidationError(line_number, "?", "bad_type", "_root", "not an object"))
        return errors
    missing = _check_required(record)
    if missing:
        errors.append(ValidationError(line_number, str(tid), missing[0], missing[1], "required field"))
        return errors
    unknown = _check_unknown_fields(record)
    if unknown:
        errors.append(ValidationError(line_number, str(tid), unknown[0], unknown[1], "not in allowed fields"))
        return errors
    typ = _check_types(record)
    if typ:
        errors.append(ValidationError(line_number, str(tid), typ[0], typ[1], typ[2]))
        return errors
    pair = _check_category_metric(record)
    if pair:
        errors.append(ValidationError(line_number, str(tid), pair[0], pair[1], pair[2]))
        return errors
    if _embedded_few_shot(record["prompt"]) and not record.get("few_shot_examples"):
        errors.append(ValidationError(line_number, str(tid), "embedded_few_shot", "prompt",
                                       "few-shot in prompt body without few_shot_examples list"))
    return errors


def validate_file(path: str) -> tuple[list[TaskSpec], list[ValidationError]]:
    validated: list[TaskSpec] = []
    errors: list[ValidationError] = []
    seen_ids: set[str] = set()
    with open(path, "r", encoding="utf-8") as fp:
        for i, raw in enumerate(fp, start=1):
            line = raw.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError as exc:
                errors.append(ValidationError(i, "?", "bad_json", "_line", str(exc)))
                continue
            line_errors = validate_task(record, line_number=i)
            if line_errors:
                errors.extend(line_errors)
                continue
            tid = record["task_id"]
            if tid in seen_ids:
                errors.append(ValidationError(i, tid, "duplicate_task_id", "task_id", "already seen"))
                continue
            seen_ids.add(tid)
            validated.append(TaskSpec(
                task_id=tid,
                category=record["category"],
                prompt=record["prompt"],
                targets=list(record["targets"]),
                metric_name=record["metric_name"],
                post_process=record["post_process"],
                few_shot_examples=list(record.get("few_shot_examples", [])),
                metadata=dict(record.get("metadata", {})),
            ))
    return validated, errors


def render_prompt(task: TaskSpec) -> str:
    parts: list[str] = []
    for ex in task.few_shot_examples:
        parts.append(f"{ex['prompt']} {ex['completion']}")
    parts.append(task.prompt)
    return "\n\n".join(parts)


CODE_BLOCK_RE = re.compile(r"```(?:[a-zA-Z0-9_]*)\n(.*?)```", re.DOTALL)
LETTER_RE = re.compile(r"(?:^|[^A-Za-z])([A-E])(?:[^A-Za-z]|$)")
LETTER_FALLBACK_RE = re.compile(r"[A-E]")


def post_process(text: str, rule: str) -> str:
    if rule == "none":
        return text
    if rule == "strip_whitespace":
        return text.strip()
    if rule == "lower":
        return text.lower()
    if rule == "extract_letter":
        m = LETTER_RE.search(text)
        if m:
            return m.group(1)
        m2 = LETTER_FALLBACK_RE.search(text)
        return m2.group(0) if m2 else ""
    if rule == "extract_code_block":
        m = CODE_BLOCK_RE.search(text)
        return m.group(1) if m else text
    if rule == "extract_first_line":
        for line in text.splitlines():
            if line.strip():
                return line.strip()
        return ""
    raise ValueError(f"unknown post_process rule: {rule}")


